# ===========================================================================
# m68k_py.py: Python 68000
# ===========================================================================
# ---------------------------------------------------------------------------
# Pure-Python 68000, a line-for-line port of Musashi 4.60 (Karl Stenerud, MIT licence) as
# the C core builds it (68000, address error + trace + RESET emulation on, prefetch off,
# no function code / PMMU emulation): same decode table, same cycle counts, same order of
# bus accesses, same flags, same exceptions (address error frame, trace, interrupts with
# auto-vectors and the auto-clear of the interrupt level, STOP, halt on a double fault).
# Checked instruction by instruction against the C Musashi (emulator/test_m68k_py.py).
#
# make_m68k(bus16, bus8, wbus16, wbus8) -> object with execute(cycles), pulse_reset(),
# set_irq(level), get_reg(n), set_reg(n, v), cycles_run(), pc().
# The bus functions get 24-bit addresses: bus16(a) a even, bus8(a), wbus16(a, v), wbus8(a, v).
# 32-bit accesses are two 16-bit ones, high word first (as neocore.c's Musashi callbacks).
# The code below is generated once at start-up: one small function per Musashi handler,
# specialised per opcode (register numbers baked in).
#
# Musashi: Copyright (c) 1998-2001 Karl Stenerud. MIT licence:
# Permission is hereby granted, free of charge, to any person obtaining a copy of this software
# and associated documentation files (the "Software"), to deal in the Software without
# restriction, including without limitation the rights to use, copy, modify, merge, publish,
# distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the
# Software is furnished to do so, subject to the following conditions:
# The above copyright notice and this permission notice shall be included in all copies or
# substantial portions of the Software.
# THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING
# BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND
# NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM,
# DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
# OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.
# ---------------------------------------------------------------------------
import base64 as _b64
import lzma as _lzma

try:                          # one-file build: the tables are inlined above
    M68K_NAMES, M68K_TABLES
except NameError:
    from m68k_tables import M68K_NAMES, M68K_TABLES

# Musashi m68ki_exception_cycle_table[0] (68000)
_CYC_EXC = ([40, 4, 50, 50, 34, 38, 40, 34, 34, 34, 34, 34, 4, 4, 4, 44] + [4] * 8 + [44] * 8 + [34] * 16
            + [4] * 208)
_SIZES = {"8": (8, "0xFF", 0, "0xFFFFFF00"), "16": (16, "0xFFFF", 8, "0xFFFF0000"),
          "32": (32, "0xFFFFFFFF", 24, "0")}
_CONDS = {
    "t": "True", "f": "False",
    "hi": "(not (fC & 0x100) and fZ)", "ls": "((fC & 0x100) or not fZ)",
    "cc": "(not (fC & 0x100))", "cs": "(fC & 0x100)",
    "ne": "fZ", "eq": "(not fZ)",
    "vc": "(not (fV & 0x80))", "vs": "(fV & 0x80)",
    "pl": "(not (fN & 0x80))", "mi": "(fN & 0x80)",
    "ge": "(not ((fN ^ fV) & 0x80))", "lt": "((fN ^ fV) & 0x80)",
    "gt": "(not ((fN ^ fV) & 0x80) and fZ)", "le": "(((fN ^ fV) & 0x80) or not fZ)",
}
_STATE = ("fN", "fZ", "fV", "fC", "fX", "fS", "T1", "T0", "IMASK", "pc", "rem", "tracing", "stopped",
          "run_mode", "instr_mode", "INT_LEVEL", "nmi_pending", "aerr_addr", "aerr_mode", "aerr_fc",
          "reset_cycles", "initial", "ppc", "ir")


def _ea(mode, sz, r):
    """Lines computing `ea` (Musashi EA_xx_MODE_SZ), r = 'ay' or 'ax' (register index variable)."""
    n = sz // 8
    if mode == "ai":
        return [f"ea = R[{r}]"]
    if mode == "pi":
        return [f"ea = R[{r}]", f"R[{r}] = (ea + {n}) & 0xFFFFFFFF"]
    if mode == "pi7":
        return ["ea = R[15]", "R[15] = (ea + 2) & 0xFFFFFFFF"]
    if mode == "pd":
        return [f"ea = R[{r}] = (R[{r}] - {n}) & 0xFFFFFFFF"]
    if mode == "pd7":
        return ["ea = R[15] = (R[15] - 2) & 0xFFFFFFFF"]
    if mode == "di":
        return ["d = imm16()", f"ea = (R[{r}] + d - ((d & 0x8000) << 1)) & 0xFFFFFFFF"]
    if mode == "ix":
        return [f"ea = ix(R[{r}])"]
    if mode == "aw":
        return ["d = imm16()", "ea = (d - ((d & 0x8000) << 1)) & 0xFFFFFFFF"]
    if mode == "al":
        return ["ea = imm32()"]
    if mode == "pcdi":
        return ["ea = pc", "d = imm16()", "ea = (ea + d - ((d & 0x8000) << 1)) & 0xFFFFFFFF"]
    if mode == "pcix":
        return ["ea = ix(pc)"]
    raise ValueError(mode)


def _rd(mode, sz):
    """Read at `ea` for an operand in `mode` (PC-relative = program space)."""
    if sz == 8:
        return "rd8(ea)"
    return f"rdp{sz}(ea)" if mode in ("pcdi", "pcix") else f"rd{sz}(ea)"


def _oper(mode, sz, var, r="ay", d="dy"):
    """Lines putting the operand (Musashi OPER_xx_MODE_SZ, or the register) into `var`."""
    mask = _SIZES[str(sz)][1]
    if mode == "d":
        return [f"{var} = R[{d}]" + ("" if sz == 32 else f" & {mask}")]
    if mode == "a":
        return [f"{var} = R[{r}]" + ("" if sz == 32 else f" & {mask}")]
    if mode == "i":
        return [f"{var} = " + {8: "imm16() & 0xFF", 16: "imm16()", 32: "imm32()"}[sz]]
    return _ea(mode, sz, r) + [f"{var} = {_rd(mode, sz)}"]


def _wr(sz, ea, val):
    return f"wr{sz}({ea}, {val})"


def _store_d(sz, reg, val):
    """Musashi *r_dst = MASK_OUT_BELOW_n(*r_dst) | val."""
    if sz == 32:
        return f"R[{reg}] = {val}"
    return f"R[{reg}] = (R[{reg}] & {_SIZES[str(sz)][3]}) | {val}"


def _flags_logic(sz, res):
    sh = _SIZES[str(sz)][2]
    return [f"fN = {res} >> {sh}" if sh else f"fN = {res}", f"fZ = {res}", "fC = 0", "fV = 0"]


def _carry(sz, r):
    """Musashi CFLAG_8/16 and, for 32 bits, CFLAG_ADD_32/SUB_32: bit 8 = carry / borrow out.
    r is the unmasked Python result (s + d, d - s), so its bit 8/16/32 is the carry."""
    return {8: r, 16: f"{r} >> 8", 32: f"{r} >> 24"}[sz]


def _gen(name):
    """Python source of the handler factory for one Musashi handler."""
    t = name.split("_")
    fam = t[0]
    L = []                                   # body lines (inside h())
    add = L.extend

    def size():
        return int(t[1])

    # ---------------------------------------------------------------- arithmetic / logic
    if fam in ("add", "sub", "cmp", "and", "or", "eor") and len(t) >= 3:
        sz = size(); sb, mask, sh, hi = _SIZES[t[1]]
        if fam == "eor":                                   # eor_SZ_MODE (Dx -> <ea>)
            mode = t[2]
            if mode == "d":
                add(["R[dy] ^= R[dx]" + ("" if sz == 32 else f" & {mask}"),
                     "res = R[dy]" + ("" if sz == 32 else f" & {mask}")] + _flags_logic(sz, "res"))
            else:
                add(_ea(mode, sz, "ay") + [f"res = (R[dx] ^ rd{sz}(ea)) & {mask}", _wr(sz, "ea", "res")]
                    + _flags_logic(sz, "res"))
        elif fam == "cmp":                                 # cmp_SZ_MODE
            mode = t[2]
            add(_oper(mode, sz, "s") + [f"dd = R[dx] & {mask}", "r = dd - s",
                f"fN = r >> {sh}" if sh else "fN = r", f"fZ = r & {mask}",
                f"fV = ((s ^ dd) & (r ^ dd)) >> {sh}" if sh else "fV = (s ^ dd) & (r ^ dd)",
                f"fC = {_carry(sz, 'r')}"])
        else:
            direction, mode = t[2], t[3]
            if direction == "er":
                add(_oper(mode, sz, "s"))
                if fam in ("add", "sub"):
                    op = "+" if fam == "add" else "-"
                    vf = "((s ^ r) & (dd ^ r))" if fam == "add" else "((s ^ dd) & (r ^ dd))"
                    add([f"dd = R[dx] & {mask}", f"r = dd {op} s",
                         f"fN = r >> {sh}" if sh else "fN = r",
                         f"fV = {vf} >> {sh}" if sh else f"fV = {vf}",
                         f"fX = fC = {_carry(sz, 'r')}", f"fZ = r & {mask}", _store_d(sz, "dx", "fZ")])
                elif fam == "and":
                    add([f"R[dx] &= s | {hi}" if sz != 32 else "R[dx] &= s",
                         f"fZ = R[dx] & {mask}", f"fN = fZ >> {sh}" if sh else "fN = fZ", "fC = 0", "fV = 0"])
                else:  # or
                    add(["R[dx] |= s", f"res = R[dx] & {mask}"] + _flags_logic(sz, "res"))
            else:                                          # re: Dx op <ea> -> <ea>
                add(_ea(mode, sz, "ay"))
                if fam in ("add", "sub"):
                    op = "+" if fam == "add" else "-"
                    vf = "((s ^ r) & (dd ^ r))" if fam == "add" else "((s ^ dd) & (r ^ dd))"
                    add([f"s = R[dx] & {mask}" if sz != 32 else "s = R[dx]", f"dd = rd{sz}(ea)", f"r = dd {op} s",
                         f"fN = r >> {sh}" if sh else "fN = r",
                         f"fV = {vf} >> {sh}" if sh else f"fV = {vf}",
                         f"fX = fC = {_carry(sz, 'r')}", f"fZ = r & {mask}", _wr(sz, "ea", "fZ")])
                elif fam == "and":
                    add([f"res = R[dx] & rd{sz}(ea)"] + _flags_logic(sz, "res") + [_wr(sz, "ea", "res")])
                else:  # or: write then flags
                    add([f"res = (R[dx] | rd{sz}(ea)) & {mask}", _wr(sz, "ea", "res")] + _flags_logic(sz, "res"))

    elif fam in ("adda", "suba", "cmpa"):
        sz = size(); mode = t[2]
        op = "+" if fam == "adda" else "-"
        add(_oper(mode, sz, "s"))
        if sz == 16:
            add(["s = (s - ((s & 0x8000) << 1)) & 0xFFFFFFFF"])
        if fam == "cmpa":
            add(["dd = R[ax]", "r = dd - s", "fN = r >> 24", "fZ = r & 0xFFFFFFFF",
                 "fV = ((s ^ dd) & (r ^ dd)) >> 24", "fC = r >> 24"])
        else:
            add([f"R[ax] = (R[ax] {op} s) & 0xFFFFFFFF"])

    elif fam in ("addi", "subi", "andi", "ori", "eori", "cmpi") and t[2] not in ("toc", "tos"):
        sz = size(); sb, mask, sh, hi = _SIZES[t[1]]; mode = t[2]
        add(_oper("i", sz, "s"))
        if fam == "cmpi":
            add(_oper(mode, sz, "dd") + ["r = dd - s", f"fN = r >> {sh}" if sh else "fN = r", f"fZ = r & {mask}",
                 f"fV = ((s ^ dd) & (r ^ dd)) >> {sh}" if sh else "fV = (s ^ dd) & (r ^ dd)",
                 f"fC = {_carry(sz, 'r')}"])
        elif fam in ("addi", "subi"):
            op = "+" if fam == "addi" else "-"
            vf = "((s ^ r) & (dd ^ r))" if fam == "addi" else "((s ^ dd) & (r ^ dd))"
            if mode == "d":
                add([f"dd = R[dy] & {mask}" if sz != 32 else "dd = R[dy]"])
            else:
                add(_ea(mode, sz, "ay") + [f"dd = rd{sz}(ea)"])
            add([f"r = dd {op} s", f"fN = r >> {sh}" if sh else "fN = r",
                 f"fV = {vf} >> {sh}" if sh else f"fV = {vf}",
                 f"fX = fC = {_carry(sz, 'r')}", f"fZ = r & {mask}",
                 _store_d(sz, "dy", "fZ") if mode == "d" else _wr(sz, "ea", "fZ")])
        else:
            op = {"andi": "&", "ori": "|", "eori": "^"}[fam]
            if mode == "d":
                if fam == "andi":
                    add([f"R[dy] &= s | {hi}" if sz != 32 else "R[dy] &= s",
                         f"fZ = R[dy] & {mask}", f"fN = fZ >> {sh}" if sh else "fN = fZ", "fC = 0", "fV = 0"])
                else:
                    add([f"R[dy] {op}= s", f"res = R[dy] & {mask}"] + _flags_logic(sz, "res"))
            else:
                add(_ea(mode, sz, "ay") + [f"res = s {op} rd{sz}(ea)"])
                if fam == "andi":
                    add(_flags_logic(sz, "res") + [_wr(sz, "ea", "res")])
                else:
                    add([_wr(sz, "ea", "res")] + _flags_logic(sz, "res"))

    elif fam in ("andi", "ori", "eori"):                   # to CCR / SR
        op = {"andi": "&", "ori": "|", "eori": "^"}[fam]
        if t[2] == "toc":
            add([f"set_ccr(get_ccr() {op} (imm16() & 0xFF))"])
        else:
            add(["if fS:", "    s = imm16()", f"    set_sr(get_sr() {op} s)", "else:", "    exception_privilege()"])

    elif fam in ("addq", "subq"):
        sz = size(); sb, mask, sh, hi = _SIZES[t[1]]; mode = t[2]
        op = "+" if fam == "addq" else "-"
        if mode == "a":
            add([f"R[ay] = (R[ay] {op} q) & 0xFFFFFFFF"])
        else:
            vf = "((s ^ r) & (dd ^ r))" if fam == "addq" else "((s ^ dd) & (r ^ dd))"
            add(["s = q"])
            if mode == "d":
                add([f"dd = R[dy] & {mask}" if sz != 32 else "dd = R[dy]"])
            else:
                add(_ea(mode, sz, "ay") + [f"dd = rd{sz}(ea)"])
            add([f"r = dd {op} s", f"fN = r >> {sh}" if sh else "fN = r",
                 f"fV = {vf} >> {sh}" if sh else f"fV = {vf}",
                 f"fX = fC = {_carry(sz, 'r')}", f"fZ = r & {mask}",
                 _store_d(sz, "dy", "fZ") if mode == "d" else _wr(sz, "ea", "fZ")])

    elif fam in ("addx", "subx"):
        sz = size(); sb, mask, sh, hi = _SIZES[t[1]]
        op = "+" if fam == "addx" else "-"
        vf = "((s ^ r) & (dd ^ r))" if fam == "addx" else "((s ^ dd) & (r ^ dd))"
        if t[2] == "rr":
            add([f"s = R[dy] & {mask}" if sz != 32 else "s = R[dy]", f"dd = R[dx] & {mask}" if sz != 32 else "dd = R[dx]"])
        else:
            v = t[3] if len(t) > 3 else ""
            add(_oper("pd7" if v in ("ay7", "axy7") else "pd", sz, "s"))
            add(_ea("pd7" if v in ("ax7", "axy7") else "pd", sz, "ax") + [f"dd = rd{sz}(ea)"])
        add([f"r = dd {op} s {op} ((fX >> 8) & 1)", f"fN = r >> {sh}" if sh else "fN = r",
             f"fV = {vf} >> {sh}" if sh else f"fV = {vf}", f"fX = fC = {_carry(sz, 'r')}",
             f"r &= {mask}", "fZ |= r", _store_d(sz, "dx", "r") if t[2] == "rr" else _wr(sz, "ea", "r")])

    elif fam in ("abcd", "sbcd"):
        if t[2] == "rr":
            add(["s = R[dy]", "dd = R[dx]"])
        else:
            v = t[3] if len(t) > 3 else ""
            add(_oper("pd7" if v in ("ay7", "axy7") else "pd", 8, "s"))
            add(_ea("pd7" if v in ("ax7", "axy7") else "pd", 8, "ax") + ["dd = rd8(ea)"])
        if fam == "abcd":
            add(["r = (s & 0x0F) + (dd & 0x0F) + ((fX >> 8) & 1)", "fV = ~r", "if r > 9:", "    r += 6",
                 "r += (s & 0xF0) + (dd & 0xF0)", "fX = fC = (r > 0x99) << 8", "if fC:", "    r -= 0xA0"])
        else:  # C unsigned arithmetic: keep r modulo 2^32
            add(["r = ((dd & 0x0F) - (s & 0x0F) - ((fX >> 8) & 1)) & 0xFFFFFFFF", "fV = ~r", "if r > 9:",
                 "    r = (r - 6) & 0xFFFFFFFF", "r = (r + (dd & 0xF0) - (s & 0xF0)) & 0xFFFFFFFF",
                 "fX = fC = (r > 0x99) << 8", "if fC:", "    r = (r + 0xA0) & 0xFFFFFFFF"])
        if fam == "abcd":
            add(["fV &= r", "fN = r", "r &= 0xFF"])
        else:
            add(["r &= 0xFF", "fV &= r", "fN = r"])
        add(["fZ |= r", _store_d(8, "dx", "r") if t[2] == "rr" else "wr8(ea, r)"])

    elif fam == "nbcd":
        mode = t[2]
        if mode == "d":
            add(["dd = R[dy]"])
        else:
            add(_ea(mode, 8, "ay") + ["dd = rd8(ea)"])
        add(["r = (0x9A - dd - ((fX >> 8) & 1)) & 0xFF", "if r != 0x9A:", "    fV = ~r",
             "    if (r & 0x0F) == 0x0A:", "        r = (r & 0xF0) + 0x10", "    r &= 0xFF", "    fV &= r",
             "    " + (_store_d(8, "dy", "r") if mode == "d" else "wr8(ea, r)"),
             "    fZ |= r", "    fC = fX = 0x100", "else:", "    fV = 0", "    fC = fX = 0", "fN = r"])

    elif fam == "cmpm":
        sz = size(); sb, mask, sh, hi = _SIZES[t[1]]
        v = t[2] if len(t) > 2 else ""
        add(_oper("pi7" if v in ("ay7", "axy7") else "pi", sz, "s"))
        add(_oper("pi7" if v in ("ax7", "axy7") else "pi", sz, "dd", r="ax"))
        add(["r = dd - s", f"fN = r >> {sh}" if sh else "fN = r", f"fZ = r & {mask}",
             f"fV = ((s ^ dd) & (r ^ dd)) >> {sh}" if sh else "fV = (s ^ dd) & (r ^ dd)", f"fC = {_carry(sz, 'r')}"])

    # ---------------------------------------------------------------- single operand
    elif fam in ("neg", "negx"):
        sz = size(); sb, mask, sh, hi = _SIZES[t[1]]; mode = t[2]
        if mode == "d":
            add(["src = R[dy]"])
        else:
            add(_ea(mode, sz, "ay") + [f"src = rd{sz}(ea)"])
        x = " - ((fX >> 8) & 1)" if fam == "negx" else ""
        add([f"r = 0 - (src & {mask}){x}", f"fN = r >> {sh}" if sh else "fN = r"])
        if sz == 32:   # CFLAG_SUB_32(src, 0, res) = (src | res) >> 23
            add(["fX = fC = (src | (r & 0xFFFFFFFF)) >> 23"])
        else:
            add([f"fX = fC = {_carry(sz, 'r')}"])
        add([f"fV = (src & r) >> {sh}" if sh else "fV = src & r", f"r &= {mask}"])
        add(["fZ |= r" if fam == "negx" else "fZ = r",
             _store_d(sz, "dy", "r") if mode == "d" else _wr(sz, "ea", "r")])

    elif fam == "not":
        sz = size(); sb, mask, sh, hi = _SIZES[t[1]]; mode = t[2]
        if mode == "d":
            add([f"res = ~R[dy] & {mask}", _store_d(sz, "dy", "res")] + _flags_logic(sz, "res"))
        else:
            add(_ea(mode, sz, "ay") + [f"res = ~rd{sz}(ea) & {mask}", _wr(sz, "ea", "res")] + _flags_logic(sz, "res"))

    elif fam == "clr":
        sz = size(); sb, mask, sh, hi = _SIZES[t[1]]; mode = t[2]
        if mode == "d":
            add([f"R[dy] &= {hi}"])
        else:
            add(_ea(mode, sz, "ay") + [_wr(sz, "ea", "0")])
        add(["fN = 0", "fV = 0", "fC = 0", "fZ = 0"])

    elif fam == "tst":
        sz = size(); mode = t[2]
        add(_oper(mode, sz, "res") + _flags_logic(sz, "res"))

    elif fam == "tas":
        mode = t[2]
        if mode == "d":
            add(["fZ = R[dy] & 0xFF", "fN = fZ", "fV = 0", "fC = 0", "R[dy] |= 0x80"])
        else:
            add(_ea(mode, 8, "ay") + ["dd = rd8(ea)", "fZ = dd", "fN = dd", "fV = 0", "fC = 0", "wr8(ea, dd | 0x80)"])

    elif fam[0] == "s" and fam[1:] in _CONDS and t[1] == "8":   # Scc
        cond = _CONDS[fam[1:]]; mode = t[2]
        if mode == "d":
            if fam == "st":
                add(["R[dy] |= 0xFF"])
            elif fam == "sf":
                add(["R[dy] &= 0xFFFFFF00"])
            else:
                add([f"if {cond}:", "    R[dy] |= 0xFF", "    rem -= 2", "else:", "    R[dy] &= 0xFFFFFF00"])
        else:
            val = {"st": "0xFF", "sf": "0"}.get(fam, f"(0xFF if {cond} else 0)")
            add(_ea(mode, 8, "ay") + [f"wr8(ea, {val})"])

    # ---------------------------------------------------------------- bits
    elif fam in ("btst", "bchg", "bclr", "bset"):
        sz = size(); kind, mode = t[2], t[3]
        if sz == 32:   # data register, bit modulo 32
            add(["m = 1 << (R[dx] & 31)" if kind == "r" else "m = 1 << (imm16() & 31)"])
            if fam == "btst":
                add(["fZ = R[dy] & m"])
            else:
                add(["fZ = R[dy] & m", {"bchg": "R[dy] ^= m", "bclr": "R[dy] &= ~m", "bset": "R[dy] |= m"}[fam]])
        elif fam == "btst":
            if kind == "r":
                add(_oper(mode, 8, "v") + ["fZ = v & (1 << (R[dx] & 7))"])
            else:
                add(["b = imm16() & 7"] + _oper(mode, 8, "v") + ["fZ = v & (1 << b)"])
        else:
            if kind == "s":
                add(["m = 1 << (imm16() & 7)"] + _ea(mode, 8, "ay") + ["v = rd8(ea)"])
            else:
                add(_ea(mode, 8, "ay") + ["v = rd8(ea)", "m = 1 << (R[dx] & 7)"])
            add(["fZ = v & m", "wr8(ea, " + {"bchg": "v ^ m", "bclr": "v & ~m", "bset": "v | m"}[fam] + ")"])

    # ---------------------------------------------------------------- shifts / rotates
    elif fam in ("asl", "asr", "lsl", "lsr", "rol", "ror", "roxl", "roxr") and t[2] not in ("r", "s"):
        mode = t[2]                                         # memory, word, shift by 1
        add(_ea(mode, 16, "ay") + ["src = rd16(ea)"])
        if fam == "asl":
            add(["res = (src << 1) & 0xFFFF", "wr16(ea, res)", "fN = res >> 8", "fZ = res", "fX = fC = src >> 7",
                 "src &= 0xC000", "fV = 0 if (src == 0 or src == 0xC000) else 0x80"])
        elif fam == "asr":
            add(["res = src >> 1", "if src & 0x8000:", "    res |= 0x8000", "wr16(ea, res)", "fN = res >> 8",
                 "fZ = res", "fV = 0", "fC = fX = src << 8"])
        elif fam == "lsl":
            add(["res = (src << 1) & 0xFFFF", "wr16(ea, res)", "fN = res >> 8", "fZ = res", "fX = fC = src >> 7", "fV = 0"])
        elif fam == "lsr":
            add(["res = src >> 1", "wr16(ea, res)", "fN = 0", "fZ = res", "fC = fX = src << 8", "fV = 0"])
        elif fam == "rol":
            add(["res = ((src << 1) | (src >> 15)) & 0xFFFF", "wr16(ea, res)", "fN = res >> 8", "fZ = res",
                 "fC = src >> 7", "fV = 0"])
        elif fam == "ror":
            add(["res = ((src >> 1) | (src << 15)) & 0xFFFF", "wr16(ea, res)", "fN = res >> 8", "fZ = res",
                 "fC = src << 8", "fV = 0"])
        elif fam == "roxl":
            add(["v = src | (((fX >> 8) & 1) << 16)", "res = (v << 1) | (v >> 16)", "fC = fX = res >> 8",
                 "res &= 0xFFFF", "wr16(ea, res)", "fN = res >> 8", "fZ = res", "fV = 0"])
        else:
            add(["v = src | (((fX >> 8) & 1) << 16)", "res = (v >> 1) | (v << 16)", "fC = fX = res >> 8",
                 "res &= 0xFFFF", "wr16(ea, res)", "fN = res >> 8", "fZ = res", "fV = 0"])

    elif fam in ("asl", "asr", "lsl", "lsr", "rol", "ror", "roxl", "roxr"):
        add(_shift_reg(fam, int(t[1]), t[2]))

    # ---------------------------------------------------------------- moves
    elif fam == "move" and t[2] in ("frs", "toc", "tos", "fru", "tou"):
        kind = t[2]; mode = t[3] if len(t) > 3 else None
        if kind == "frs":   # 68000: not privileged
            if mode == "d":
                add(["R[dy] = (R[dy] & 0xFFFF0000) | get_sr()"])
            else:
                add(_ea(mode, 16, "ay") + ["wr16(ea, get_sr())"])
        elif kind == "toc":
            add(_oper(mode, 16, "v") + ["set_ccr(v)"])
        elif kind == "tos":
            add(["if fS:"] + ["    " + x for x in _oper(mode, 16, "v")] + ["    set_sr(v)", "else:",
                 "    exception_privilege()"])
        elif kind == "fru":
            add(["if fS:", "    R[ay] = SPB[0]", "else:", "    exception_privilege()"])
        else:
            add(["if fS:", "    SPB[0] = R[ay]", "else:", "    exception_privilege()"])

    elif fam == "move":
        sz = size(); sb, mask, sh, hi = _SIZES[t[1]]; dmode, smode = t[2], t[3]
        add(_oper(smode, sz, "res"))
        if dmode == "d":
            add([_store_d(sz, "dx", "res")])
        else:
            add(_ea(dmode, sz, "ax"))
            if sz == 32 and dmode == "pd":          # MOVE.L -(An): low word first (Musashi)
                add(["wr16((ea + 2) & 0xFFFFFFFF, res & 0xFFFF)", "wr16(ea, res >> 16)"])
            else:
                add([_wr(sz, "ea", "res")])
        add(_flags_logic(sz, "res"))

    elif fam == "movea":
        sz = size(); mode = t[2]
        add(_oper(mode, sz, "v"))
        add(["R[ax] = (v - ((v & 0x8000) << 1)) & 0xFFFFFFFF" if sz == 16 else "R[ax] = v"])

    elif fam == "moveq":
        add(["res = R[dx] = q8", "fN = res >> 24", "fZ = res", "fV = 0", "fC = 0"])

    elif fam == "movem":
        sz = size(); direction, mode = t[2], t[3]
        n = sz // 8
        add(["lst = imm16()"])
        if mode in ("pi", "pd"):
            add(["ea = R[ay]"])
        else:
            add(_ea(mode, sz, "ay"))
        add(["count = 0", "i = 0", "while lst:", "    if lst & 1:"])
        if direction == "er":
            rd = (f"rdp{sz}(ea)" if mode in ("pcdi", "pcix") else f"rd{sz}(ea)")
            if sz == 16:
                add([f"        v = {rd}", "        R[i] = (v - ((v & 0x8000) << 1)) & 0xFFFFFFFF"])
            else:
                add([f"        R[i] = {rd}"])
            add([f"        ea = (ea + {n}) & 0xFFFFFFFF", "        count += 1"])
        elif mode == "pd":
            add([f"        ea = (ea - {n}) & 0xFFFFFFFF"])
            if sz == 16:
                add(["        wr16(ea, R[15 - i] & 0xFFFF)"])
            else:
                add(["        wr16((ea + 2) & 0xFFFFFFFF, R[15 - i] & 0xFFFF)", "        wr16(ea, R[15 - i] >> 16)"])
            add(["        count += 1"])
        else:
            add([f"        wr{sz}(ea, R[i]" + (" & 0xFFFF)" if sz == 16 else ")"),
                 f"        ea = (ea + {n}) & 0xFFFFFFFF", "        count += 1"])
        add(["    lst >>= 1", "    i += 1"])
        if mode in ("pi", "pd"):
            add(["R[ay] = ea"])
        add([f"rem -= count << {2 if sz == 16 else 3}"])

    elif fam == "movep":
        sz = size(); direction = t[2]
        add(_ea("di", sz, "ay"))
        if direction == "er":
            if sz == 16:
                add(["v = rd8(ea) << 8", "v += rd8((ea + 2) & 0xFFFFFFFF)", "R[dx] = (R[dx] & 0xFFFF0000) | v"])
            else:
                add(["v = rd8(ea) << 24", "v += rd8((ea + 2) & 0xFFFFFFFF) << 16", "v += rd8((ea + 4) & 0xFFFFFFFF) << 8",
                     "v += rd8((ea + 6) & 0xFFFFFFFF)", "R[dx] = v"])
        else:
            add(["s = R[dx]"])
            shifts = (8, 0) if sz == 16 else (24, 16, 8, 0)
            for k, shf in enumerate(shifts):
                add([f"wr8((ea + {2 * k}) & 0xFFFFFFFF, (s >> {shf}) & 0xFF)" if k else f"wr8(ea, (s >> {shf}) & 0xFF)"])

    elif fam == "move16":
        add(["w2 = imm16()", "rx_ = 8 + (ir & 7)", "ry_ = 8 + ((w2 >> 12) & 7)",
             "wr32(R[ry_], rd32(R[rx_]))", "wr32((R[ry_] + 4) & 0xFFFFFFFF, rd32((R[rx_] + 4) & 0xFFFFFFFF))",
             "wr32((R[ry_] + 8) & 0xFFFFFFFF, rd32((R[rx_] + 8) & 0xFFFFFFFF))",
             "wr32((R[ry_] + 12) & 0xFFFFFFFF, rd32((R[rx_] + 12) & 0xFFFFFFFF))",
             "R[rx_] = (R[rx_] + 16) & 0xFFFFFFFF", "R[ry_] = (R[ry_] + 16) & 0xFFFFFFFF"])

    # ---------------------------------------------------------------- multiply / divide / chk
    elif fam in ("mulu", "muls"):
        mode = t[2]
        add(_oper(mode, 16, "x"))
        if fam == "mulu":
            add(["rem -= bin(x).count('1') << 1", "res = x * (R[dx] & 0xFFFF)"])
        else:
            add(["x = (x - ((x & 0x8000) << 1)) & 0xFFFFFFFF",
                 "rem -= bin((x ^ (x << 1)) & ((1 << x.bit_length()) - 1)).count('1') << 1",
                 "dd = R[dx] & 0xFFFF", "res = (x * (dd - ((dd & 0x8000) << 1))) & 0xFFFFFFFF"])
        add(["R[dx] = res", "fZ = res", "fN = res >> 24", "fV = 0", "fC = 0"])

    elif fam == "divu":
        add(_oper(t[2], 16, "s") + ["if s:", "    dd = R[dx]", "    qu = dd // s", "    if qu < 0x10000:",
             "        fZ = qu", "        fN = qu >> 8", "        fV = 0", "        fC = 0",
             "        R[dx] = (qu | ((dd % s) << 16)) & 0xFFFFFFFF", "    else:", "        fV = 0x80",
             "else:", "    exception_trap(5)"])

    elif fam == "divs":
        add(_oper(t[2], 16, "s") + ["s -= (s & 0x8000) << 1", "if s:",
             "    if R[dx] == 0x80000000 and s == -1:", "        fZ = 0", "        fN = 0", "        fV = 0",
             "        fC = 0", "        R[dx] = 0", "    else:",
             "        dd = R[dx] - ((R[dx] & 0x80000000) << 1)",
             "        qu = abs(dd) // abs(s)", "        if (dd < 0) != (s < 0):", "            qu = -qu",
             "        rm = dd - qu * s",
             "        if -0x8000 <= qu <= 0x7FFF:", "            fZ = qu & 0xFFFFFFFF", "            fN = qu >> 8",
             "            fV = 0", "            fC = 0", "            R[dx] = ((qu & 0xFFFF) | (rm << 16)) & 0xFFFFFFFF",
             "        else:", "            fV = 0x80", "else:", "    exception_trap(5)"])

    elif fam == "chk":
        add(["src = R[dx] & 0xFFFF", "src -= (src & 0x8000) << 1"] + _oper(t[2], 16, "b")
            + ["b -= (b & 0x8000) << 1", "fZ = src & 0xFFFF", "fV = 0", "fC = 0", "if not (0 <= src <= b):",
               "    fN = 0x80 if src < 0 else 0", "    exception_trap(6)"])

    # ---------------------------------------------------------------- flow
    elif fam in ("bra", "bsr") or (fam[0] == "b" and fam[1:] in _CONDS and len(t) == 2):
        long_ = t[1] == "16"
        if fam == "bsr":
            if long_:
                add(["off = imm16()", "push32(pc)", "pc = (pc - 2 + off - ((off & 0x8000) << 1)) & 0xFFFFFFFF"])
            else:
                add(["push32(pc)", "pc = (pc + q8) & 0xFFFFFFFF"])
        elif fam == "bra":
            if long_:
                add(["off = imm16()", "pc = (pc - 2 + off - ((off & 0x8000) << 1)) & 0xFFFFFFFF"])
            else:
                add(["pc = (pc + q8) & 0xFFFFFFFF"])
            add(["if pc == ppc:", "    rem = cmod(rem, CYC[ir])"])
        else:
            cond = _CONDS[fam[1:]]
            if long_:
                add([f"if {cond}:", "    off = imm16()", "    pc = (pc - 2 + off - ((off & 0x8000) << 1)) & 0xFFFFFFFF",
                     "else:", "    pc = (pc + 2) & 0xFFFFFFFF", "    rem -= 2"])
            else:
                add([f"if {cond}:", "    pc = (pc + q8) & 0xFFFFFFFF", "else:", "    rem += 2"])

    elif fam.startswith("db"):
        cond = fam[2:]
        dbf = ["v = (R[dy] - 1) & 0xFFFF", "R[dy] = (R[dy] & 0xFFFF0000) | v", "if v != 0xFFFF:",
               "    off = imm16()", "    pc = (pc - 2 + off - ((off & 0x8000) << 1)) & 0xFFFFFFFF", "    rem += 2",
               "else:", "    pc = (pc + 2) & 0xFFFFFFFF", "    rem -= 2"]
        if cond == "f":
            add(dbf)
        elif cond == "t":
            add(["pc = (pc + 2) & 0xFFFFFFFF"])
        else:
            add([f"if not {_CONDS[cond]}:"] + ["    " + x for x in dbf] + ["else:", "    pc = (pc + 2) & 0xFFFFFFFF"])

    elif fam in ("jmp", "jsr", "lea", "pea"):
        add(_ea(t[2], 32, "ay"))
        add({"jmp": ["pc = ea", "if pc == ppc:", "    rem = cmod(rem, CYC[ir])"],
             "jsr": ["push32(pc)", "pc = ea"], "lea": ["R[ax] = ea"], "pea": ["push32(ea)"]}[fam])

    elif fam == "link":
        if len(t) > 2:   # a7
            add(["R[15] = (R[15] - 4) & 0xFFFFFFFF", "wr32(R[15], R[15])"])
        else:
            add(["push32(R[ay])", "R[ay] = R[15]"])
        add(["d = imm16()", "R[15] = (R[15] + d - ((d & 0x8000) << 1)) & 0xFFFFFFFF"])
    elif fam == "unlk":
        if len(t) > 2:
            add(["R[15] = rd32(R[15])"])
        else:
            add(["R[15] = R[ay]", "R[ay] = pull32()"])
    elif fam == "rts":
        add(["pc = pull32()"])
    elif fam == "rtr":
        add(["set_ccr(pull16())", "pc = pull32()"])
    elif fam == "rte":
        add(["if fS:", "    nsr = pull16()", "    npc = pull32()", "    pc = npc", "    set_sr(nsr)",
             "    instr_mode = 0", "    run_mode = 0", "else:", "    exception_privilege()"])
    elif fam == "trap":
        add(["exception_trapN(32 + (ir & 15))"])
    elif fam == "trapv":
        add(["if fV & 0x80:", "    exception_trap(7)"])
    elif fam in ("illegal",) or name == "x_illegal":
        add(["exception_illegal()"])
    elif fam == "1010":
        add(["exception_line(10)"])
    elif fam == "1111" or name == "x_1111":
        add(["exception_line(11)"])
    elif fam == "nop":
        add(["pass"])
    elif fam == "stop":
        add(["if fS:", "    nsr = imm16()", "    stopped |= 1", "    set_sr(nsr)", "    c = CYC[ir]",
             "    if rem >= c:", "        rem = c", "    else:", "        rem = cmod(rem, c)", "else:",
             "    exception_privilege()"])
    elif fam == "reset":
        add(["if fS:", "    reset_cb()", "    rem -= 132", "else:", "    exception_privilege()"])
    elif fam == "ext":
        if t[1] == "16":
            add(["v = R[dy]", "v = (v & 0xFFFF0000) | (v & 0xFF) | (0xFF00 if v & 0x80 else 0)", "R[dy] = v",
                 "fN = v >> 8", "fZ = v & 0xFFFF", "fV = 0", "fC = 0"])
        else:
            add(["v = R[dy]", "v = (v & 0xFFFF) | (0xFFFF0000 if v & 0x8000 else 0)", "R[dy] = v",
                 "fN = v >> 24", "fZ = v", "fV = 0", "fC = 0"])
    elif fam == "swap":
        add(["v = R[dy]", "v = ((v << 16) & 0xFFFFFFFF) | (v >> 16)", "R[dy] = v", "fZ = v", "fN = v >> 24",
             "fC = 0", "fV = 0"])
    elif fam == "exg":
        a, b = {"dd": ("dx", "dy"), "aa": ("ax", "ay"), "da": ("dx", "ay")}[t[2]]
        add([f"R[{a}], R[{b}] = R[{b}], R[{a}]"])
    else:
        raise ValueError(f"no Python handler for {name}")
    return L


def _shift_reg(fam, sz, kind):
    """Register shifts and rotates (Musashi asl_8_s ... roxr_32_r), ported line by line."""
    sb, mask, sh, hi = _SIZES[str(sz)]
    tbl = f"SH{sz}"
    L = []
    if kind == "s":
        L.append("shift = q")
    else:
        L.append("shift = R[dx] & 0x3F")
    src = f"src = R[dy] & {mask}" if sz != 32 else "src = R[dy]"
    N = (lambda v: f"fN = {v} >> {sh}" if sh else f"fN = {v}")
    st = (lambda v: _store_d(sz, "dy", v))
    if fam in ("asl", "lsl"):
        L += [src, f"res = (src << shift) & {mask}"]
        if kind == "s":
            L += ["rem -= shift << 1", st("res"), N("res"), "fZ = res"]
            L += [{8: "fX = fC = src << shift", 16: "fX = fC = src >> (8 - shift)",
                   32: "fX = fC = src >> (24 - shift)"}[sz]]
            if fam == "asl":
                L += [f"t = {tbl}[shift + 1]", "src &= t"]
                L += ["fV = 0 if (src == 0 or (src == t and shift < 8)) else 0x80" if sz == 8 else
                      "fV = 0 if (src == 0 or src == t) else 0x80"]
            else:
                L += ["fV = 0"]
            return L
        lim = sz if (fam == "asl" or sz == 32) else sz + 1     # asl: < sz ; lsl 8/16: <= sz ; lsl 32: < 32
        L += ["if shift:", "    rem -= shift << 1", f"    if shift < {lim}:", "        " + st("res"),
              "        fX = fC = " + {8: "src << shift", 16: "(src << shift) >> 8", 32: "(src >> (32 - shift)) << 8"}[sz],
              "        " + N("res"), "        fZ = res"]
        if fam == "asl":
            L += [f"        t = {tbl}[shift + 1]", "        src &= t",
                  "        fV = 0 if (src == 0 or src == t) else 0x80", "    else:",
                  "        R[dy] &= " + (hi if sz != 32 else "0"),
                  f"        fX = fC = (src & 1) << 8 if shift == {sz} else 0",
                  "        fN = 0", "        fZ = 0", "        fV = 0 if src == 0 else 0x80"]
        else:
            L += ["        fV = 0", "    else:", "        R[dy] &= " + (hi if sz != 32 else "0")]
            if sz == 32:
                L += ["        fX = fC = (src & 1) << 8 if shift == 32 else 0"]
            else:
                L += ["        fX = fC = 0"]
            L += ["        fN = 0", "        fZ = 0", "        fV = 0"]
        L += ["else:", "    fC = 0", "    " + N("src"), "    fZ = src", "    fV = 0"]
        return L
    if fam in ("asr", "lsr"):
        L += [src, "res = src >> shift"]
        if kind == "s":
            L += ["rem -= shift << 1"]
            if fam == "asr":
                L += [f"if src & {hex(1 << (sz - 1))}:", f"    res |= {tbl}[shift]", st("res"), N("res"), "fZ = res",
                      "fV = 0", "fX = fC = src << (9 - shift)"]
            else:
                L += [st("res"), "fN = 0", "fZ = res", "fX = fC = src << (9 - shift)", "fV = 0"]
            return L
        msb = hex(1 << (sz - 1))
        if fam == "asr":
            L += ["if shift:", "    rem -= shift << 1", f"    if shift < {sz}:", f"        if src & {msb}:",
                  f"            res |= {tbl}[shift]", "        " + st("res"),
                  "        fX = fC = " + ("src << (9 - shift)" if sz == 8 else "(src >> (shift - 1)) << 8"),
                  "        " + N("res"), "        fZ = res", "        fV = 0",
                  f"    elif src & {msb}:", "        R[dy] |= " + mask, "        fC = fX = 0x100", "        fN = 0x80",
                  "        fZ = 0xFFFFFFFF", "        fV = 0",
                  "    else:", "        R[dy] &= " + (hi if sz != 32 else "0"), "        fC = fX = 0", "        fN = 0",
                  "        fZ = 0", "        fV = 0"]
        else:
            lim = f"shift <= {sz}" if sz != 32 else "shift < 32"
            L += ["if shift:", "    rem -= shift << 1", f"    if {lim}:", "        " + st("res"),
                  "        fX = fC = " + ("src << (9 - shift)" if sz == 8 else "(src >> (shift - 1)) << 8"),
                  "        fN = 0", "        fZ = res", "        fV = 0",
                  "    else:", "        R[dy] &= " + (hi if sz != 32 else "0")]
            L += ["        fX = fC = ((src >> 31) << 8) if shift == 32 else 0" if sz == 32 else "        fX = fC = 0"]
            L += ["        fN = 0", "        fZ = 0", "        fV = 0"]
        L += ["else:", "    fC = 0", "    " + N("src"), "    fZ = src", "    fV = 0"]
        return L
    if fam in ("rol", "ror"):
        L += [src]
        if kind == "s":
            L += ["orig = shift", f"shift = orig & {sz - 1}"]
        else:
            L += ["orig = shift", f"shift = orig & {sz - 1}"]
        if fam == "rol":
            L += [f"res = ((src << shift) | (src >> ({sz} - shift))) & {mask}"]
        else:
            L += [f"res = ((src >> shift) | (src << ({sz} - shift))) & {mask}"]
        if kind == "s":
            L += ["rem -= orig << 1", st("res"), N("res"), "fZ = res"]
            if fam == "rol":
                L += [{8: "fC = src << orig", 16: "fC = src >> (8 - shift)", 32: "fC = src >> (24 - shift)"}[sz]]
            else:
                L += [{8: "fC = src << (9 - orig)", 16: "fC = src << (9 - shift)", 32: "fC = src << (9 - shift)"}[sz]]
            L += ["fV = 0"]
            return L
        if fam == "rol" and sz != 32:
            L += ["if orig:", "    rem -= orig << 1", "    if shift:", "        " + st("res"),
                  "        fC = " + ("src << shift" if sz == 8 else "(src << shift) >> 8"),
                  "        " + N("res"), "        fZ = res", "        fV = 0", "    else:", "        fC = (src & 1) << 8",
                  "        " + N("src"), "        fZ = src", "        fV = 0"]
        else:
            if fam == "rol":     # 32
                cexp = "(src >> ((32 - shift) & 31)) << 8"
            else:
                cexp = {8: "src << (8 - ((shift - 1) & 7))", 16: "(src >> ((shift - 1) & 15)) << 8",
                        32: "(src >> ((shift - 1) & 31)) << 8"}[sz]
            L += ["if orig:", "    rem -= orig << 1", "    " + st("res"), "    fC = " + cexp, "    " + N("res"),
                  "    fZ = res", "    fV = 0"]
        L += ["else:", "    fC = 0", "    " + N("src"), "    fZ = src", "    fV = 0"]
        return L
    # roxl / roxr: rotate through X, (sz + 1)-bit value
    w = sz + 1
    rot = (f"res = (v << shift) | (v >> ({w} - shift))" if fam == "roxl" else
           f"res = (v >> shift) | (v << ({w} - shift))")
    cx = {8: "fC = fX = res", 16: "fC = fX = res >> 8", 32: "fC = fX = res >> 24"}[sz]
    body = [src, f"v = src | (((fX >> 8) & 1) << {sz})", rot]
    if sz == 32:   # uint64 arithmetic: keep 64 bits
        body.append("res &= 0xFFFFFFFFFFFFFFFF")
    if kind == "s":
        L += body + ["rem -= shift << 1", cx, f"res &= {mask}", st("res"), N("res"), "fZ = res", "fV = 0"]
        return L
    L += ["if shift:", "    orig = shift", f"    shift = orig % {w}"] + ["    " + x for x in body]
    L += ["    rem -= orig << 1", "    " + cx, f"    res &= {mask}", "    " + st("res"), "    " + N("res"),
          "    fZ = res", "    fV = 0", "else:", "    fC = fX", "    " + N("R[dy]"),
          f"    fZ = R[dy] & {mask}", "    fV = 0"]
    return L


_RUNTIME = r'''
def _build(bus16, bus8, wbus16, wbus8, reset_cb, CYC, H_NAMES, H_INDEX, FAST, FW):
    # FAST[0] true: a 16-bit read at $C00000-$CFFFFF (the BIOS socket, mirrored every 128 KB) is
    # FW[a & 0x1FFFE], without calling bus16. The bus owner keeps FW equal to its BIOS words and
    # clears FAST[0] whenever such a read must be seen (host port armed, faults, watch hook).
    # Used for the opcode and extension word fetches only: same values, same order, no side effect.
    R = [0] * 16                 # D0-D7, A0-A7 (A7 = active stack pointer)
    SPB = [0] * 8                # Musashi REG_SP_BASE: [0] USP, [4] ISP
    SH8 = [0, 0x80, 0xC0, 0xE0, 0xF0, 0xF8, 0xFC, 0xFE] + [0xFF] * 57
    SH16 = [(0xFFFF << (16 - i)) & 0xFFFF for i in range(17)] + [0xFFFF] * 48
    SH32 = [(0xFFFFFFFF << (32 - i)) & 0xFFFFFFFF for i in range(33)] + [0xFFFFFFFF] * 32
    CYC_EXC = %(cyc_exc)r
    fN = fZ = fV = fC = fX = 0
    fS = 0
    T1 = T0 = 0
    IMASK = 0x700
    INT_LEVEL = 0
    nmi_pending = False
    pc = ppc = ir = 0
    rem = initial = 0
    reset_cycles = 0
    tracing = 0
    stopped = 0
    run_mode = 0
    instr_mode = 0
    aerr_addr = aerr_mode = aerr_fc = 0
    in_exec = False

    class AErr(Exception):
        pass

    def cmod(a, b):              # C '%%' (truncates toward zero)
        return a %% b if a >= 0 else -((-a) %% b)

    def aerr(a, mode, fc):
        nonlocal aerr_addr, aerr_mode, aerr_fc
        aerr_addr = a & 0xFFFFFFFF
        aerr_mode = mode
        aerr_fc = fc
        raise AErr()

    # ---- bus (Musashi m68ki_read/write_xx_fc, ADDRESS_68K = 24 bits)
    def rd8(a):
        return bus8(a & 0xFFFFFF)

    def rd16(a):
        if a & 1:
            aerr(a, 0x10, fS | 1)
        return bus16(a & 0xFFFFFF)

    def rd32(a):
        if a & 1:
            aerr(a, 0x10, fS | 1)
        a &= 0xFFFFFF
        return (bus16(a) << 16) | bus16((a + 2) & 0xFFFFFF)

    def rdp16(a):
        if a & 1:
            aerr(a, 0x10, fS | 2)
        return bus16(a & 0xFFFFFF)

    def rdp32(a):
        if a & 1:
            aerr(a, 0x10, fS | 2)
        a &= 0xFFFFFF
        return (bus16(a) << 16) | bus16((a + 2) & 0xFFFFFF)

    def wr8(a, v):
        wbus8(a & 0xFFFFFF, v & 0xFF)

    def wr16(a, v):
        if a & 1:
            aerr(a, 0, fS | 1)
        wbus16(a & 0xFFFFFF, v & 0xFFFF)

    def wr32(a, v):
        if a & 1:
            aerr(a, 0, fS | 1)
        a &= 0xFFFFFF
        wbus16(a, (v >> 16) & 0xFFFF)
        wbus16((a + 2) & 0xFFFFFF, v & 0xFFFF)

    def imm16():
        nonlocal pc
        a = pc
        if a & 1:
            aerr(a, 0x10, fS | 2)
        pc = (a + 2) & 0xFFFFFFFF
        a &= 0xFFFFFF
        if FAST[0] and 0xC00000 <= a < 0xD00000:
            return FW[a & 0x1FFFE]
        return bus16(a)

    def imm32():
        nonlocal pc
        a = pc
        if a & 1:
            aerr(a, 0x10, fS | 2)
        pc = (a + 4) & 0xFFFFFFFF
        a &= 0xFFFFFF
        if FAST[0] and 0xC00000 <= a < 0xCFFFFE:
            return (FW[a & 0x1FFFE] << 16) | FW[(a + 2) & 0x1FFFE]
        return (bus16(a) << 16) | bus16((a + 2) & 0xFFFFFF)

    def ix(base):                # 68000 brief extension word
        ext = imm16()
        x = R[ext >> 12]
        if not ext & 0x800:
            x = (x & 0xFFFF) - ((x & 0x8000) << 1)
        return (base + x + (ext & 0xFF) - ((ext & 0x80) << 1)) & 0xFFFFFFFF

    def push16(v):
        R[15] = (R[15] - 2) & 0xFFFFFFFF
        wr16(R[15], v)

    def push32(v):
        R[15] = (R[15] - 4) & 0xFFFFFFFF
        wr32(R[15], v)

    def pull16():
        R[15] = (R[15] + 2) & 0xFFFFFFFF
        return rd16((R[15] - 2) & 0xFFFFFFFF)

    def pull32():
        R[15] = (R[15] + 4) & 0xFFFFFFFF
        return rd32((R[15] - 4) & 0xFFFFFFFF)

    # ---- status register
    def get_ccr():
        return ((fX >> 4) & 0x10) | ((fN >> 4) & 8) | ((not fZ) << 2) | ((fV >> 6) & 2) | ((fC >> 8) & 1)

    def get_sr():
        return T1 | T0 | (fS << 11) | IMASK | get_ccr()

    def set_ccr(v):
        nonlocal fX, fN, fZ, fV, fC
        fX = (v & 0x10) << 4
        fN = (v & 8) << 4
        fZ = 0 if v & 4 else 1
        fV = (v & 2) << 6
        fC = (v & 1) << 8

    def set_s_flag(v):
        nonlocal fS
        SPB[fS] = R[15]
        fS = v
        R[15] = SPB[fS]

    def set_sr_noint(v):
        nonlocal T1, T0, IMASK
        v &= 0xA71F
        T1 = v & 0x8000
        T0 = v & 0x4000
        IMASK = v & 0x0700
        set_ccr(v)
        set_s_flag((v >> 11) & 4)

    def set_sr(v):
        set_sr_noint(v)
        check_interrupts()

    def check_interrupts():
        nonlocal nmi_pending
        if nmi_pending:
            nmi_pending = False
            exception_interrupt(7)
        elif INT_LEVEL > IMASK:
            exception_interrupt(INT_LEVEL >> 8)

    # ---- exceptions
    def init_exception():
        nonlocal T1, T0, tracing
        sr = get_sr()
        T1 = T0 = 0
        tracing = 0
        set_s_flag(4)
        return sr

    def jump_vector(v):
        nonlocal pc
        pc = rd32(v << 2)

    def exception_trap(v):
        nonlocal rem
        sr = init_exception()
        push32(pc)
        push16(sr)
        jump_vector(v)
        rem -= CYC_EXC[v] - CYC[ir]

    exception_trapN = exception_trap

    def exception_privilege():
        nonlocal rem, instr_mode
        sr = init_exception()
        instr_mode = 8
        push32(ppc)
        push16(sr)
        jump_vector(8)
        rem -= CYC_EXC[8] - CYC[ir]

    def exception_illegal():
        nonlocal rem, instr_mode
        sr = init_exception()
        instr_mode = 8
        push32(ppc)
        push16(sr)
        jump_vector(4)
        rem -= CYC_EXC[4] - CYC[ir]

    def exception_line(v):       # 1010 / 1111
        nonlocal rem
        sr = init_exception()
        push32(ppc)
        push16(sr)
        jump_vector(v)
        rem -= CYC_EXC[v] - CYC[ir]

    def exception_trace():
        nonlocal rem, instr_mode, stopped
        sr = init_exception()
        instr_mode = 8
        push32(pc)
        push16(sr)
        jump_vector(9)
        stopped &= ~1
        rem -= CYC_EXC[9]

    def exception_interrupt(level):
        nonlocal instr_mode, stopped, IMASK, pc, rem, INT_LEVEL
        instr_mode = 8
        stopped &= ~1
        if stopped:
            return
        vector = 24 + level
        sr = init_exception()
        IMASK = level << 8
        npc = rd32(vector << 2)
        if npc == 0:
            npc = rd32(15 << 2)
        push32(pc)
        push16(sr)
        pc = npc
        rem -= CYC_EXC[vector]
        INT_LEVEL = 0

    def exception_address_error():
        nonlocal run_mode, stopped, rem
        sr = init_exception()
        if run_mode == 1:        # fault while writing the frame of a bus/address error: halt
            bus8(0xFFFF01)
            stopped = 2
            return
        run_mode = 1
        push32(pc)
        push16(sr)
        push16(ir)
        push32(aerr_addr)
        push16(aerr_mode | instr_mode | aerr_fc)
        jump_vector(3)
        run_mode = 2
        rem -= CYC_EXC[3]

    def address_error_trap():    # what Musashi's setjmp block does, nested faults included
        while True:
            try:
                exception_address_error()
                return
            except AErr:
                pass

%(handlers)s
    # ---- decode table: one specialised function per opcode
    loc = dict(locals())         # (not inside the comprehension: before Python 3.12 it has its own locals())
    factories = {n: f for n, f in loc.items() if n.startswith("F_")}
    H = [None] * 0x10000
    for op in range(0x10000):
        H[op] = factories["F_" + H_NAMES[H_INDEX[op]]](op)

    def execute(num):
        nonlocal reset_cycles, rem, initial, tracing, ppc, pc, ir, in_exec, stopped
        if reset_cycles:
            rc = reset_cycles
            reset_cycles = 0
            num -= rc
            if num <= 0:
                return rc
        rem = num
        initial = num
        try:
            check_interrupts()
        except AErr:
            address_error_trap()
            if stopped:
                rem = 0
                return initial
        if stopped:
            rem = 0
            return initial
        H_ = H
        C_ = CYC
        while True:
            try:
                while True:
                    tracing = T1
                    a = ppc = pc
                    if a & 1:
                        aerr(a, 0x10, fS | 2)
                    pc = (a + 2) & 0xFFFFFFFF
                    a &= 0xFFFFFF
                    if FAST[0] and 0xC00000 <= a < 0xD00000:
                        ir = i_ = FW[a & 0x1FFFE]
                    else:
                        ir = i_ = bus16(a)
                    H_[i_]()
                    rem -= C_[i_]
                    if tracing:
                        exception_trace()
                    if rem <= 0:
                        break
                ppc = pc
                return initial - rem
            except AErr:
                address_error_trap()
                if stopped:
                    rem = 0
                    return initial
                if rem <= 0:
                    return initial - rem

    def pulse_reset():
        nonlocal stopped, rem, run_mode, instr_mode, T1, T0, tracing, IMASK, INT_LEVEL, pc, reset_cycles
        stopped = 0
        rem = 0
        run_mode = 2
        instr_mode = 0
        T1 = T0 = 0
        tracing = 0
        IMASK = 0x700
        INT_LEVEL = 0
        set_s_flag(4)
        pc = 0
        R[15] = imm32()
        pc = imm32()
        run_mode = 0
        reset_cycles = CYC_EXC[0]

    def set_irq(level):
        nonlocal INT_LEVEL, nmi_pending
        old = INT_LEVEL
        INT_LEVEL = level << 8
        if old != 0x700 and INT_LEVEL == 0x700:
            nmi_pending = True

    def cycles_run():
        return initial - rem

    def get_pc():
        return pc

    def get_reg(n):
        if n < 16:
            return R[n]
        return {16: pc, 17: get_sr(), 18: R[15], 19: R[15] if not fS else SPB[0],
                20: R[15] if fS else SPB[4], 29: ppc, 30: ir}.get(n, 0)

    def set_reg(n, v):
        nonlocal pc
        v &= 0xFFFFFFFF
        if n < 16:
            R[n] = v
        elif n == 16:
            pc = v
        elif n == 17:
            set_sr(v)
        elif n == 18:
            R[15] = v
        elif n == 19:
            if fS:
                SPB[0] = v
            else:
                R[15] = v
        elif n == 20:
            if fS:
                R[15] = v
            else:
                SPB[4] = v

    def state():
        return dict(R=list(R), pc=pc, sr=get_sr(), usp=SPB[0] if fS else R[15], isp=R[15] if fS else SPB[4],
                    stopped=stopped, run_mode=run_mode, instr_mode=instr_mode, int_level=INT_LEVEL, ppc=ppc)

    return execute, pulse_reset, set_irq, cycles_run, get_pc, get_reg, set_reg, state
'''


def _factory_src(name):
    import re
    body = _gen(name)
    text = "\n".join(body)
    assigned = [v for v in _STATE if re.search(r"(?<![\w\[.])%s\s*(?:[-+&|^]|<<|>>)?=(?!=)" % v, text)]
    pre = ["    def F_%s(op):" % name, "        dx = (op >> 9) & 7", "        dy = op & 7", "        ax = dx + 8",
           "        ay = dy + 8", "        q = (((op >> 9) - 1) & 7) + 1",
           "        q8 = ((op & 0xFF) - ((op & 0x80) << 1)) & 0xFFFFFFFF", "        def h():"]
    if assigned:
        pre.append("            nonlocal " + ", ".join(assigned))
    return "\n".join(pre + ["            " + l for l in body] + ["        return h"])


class M68K:
    """The Python 68000. Methods as Musashi's m68k_* API."""

    def __init__(self, bus16, bus8, wbus16, wbus8, reset_cb=lambda: None, names=None, tables=None, fast=None):
        """fast: (FAST, FW) from the bus owner (see _build); None = every fetch through bus16."""
        if fast is None:
            fast = ([0], [])
        if names is None:
            names, tables = M68K_NAMES, M68K_TABLES
        raw = _lzma.decompress(_b64.b64decode("".join(tables)))
        index = memoryview(raw[:0x20000]).cast("H")
        cyc = list(raw[0x20000:])
        src = _RUNTIME % {"cyc_exc": _CYC_EXC, "handlers": "\n".join(_factory_src(n) for n in names)}
        g = {}
        exec(compile(src, "<m68k_py>", "exec"), g)
        (self.execute, self.pulse_reset, self.set_irq, self.cycles_run, self.pc, self.get_reg, self.set_reg,
         self.state) = g["_build"](bus16, bus8, wbus16, wbus8, reset_cb, cyc, names, list(index), fast[0], fast[1])

# ===========================================================================
# neo_py.py: Python Neo Geo AES model
# ===========================================================================
# ---------------------------------------------------------------------------
# Pure-Python Neo Geo AES model: a line-for-line port of neocore.c (same API: neo_*), on the
# Python 68000 of m68k_py.py, with the part of the superzazu/z80 core (Nicolas Allemand, MIT
# licence) that the Z80 programs of the model run (the built-in test M1, or no program: $FF).
# Same timings, same results word for word as the C core (checked by emulator/regress_rom.py
# with CORE=python, emulator/test/test_neo_py.py).
# PyNeoLib() is used like the ctypes library: lib.neo_run_frame(), lib.neo_host_send(...);
# the output buffers can be ctypes arrays or lists.
#
# superzazu/z80: Copyright (c) 2019 Nicolas Allemand. MIT licence, same
# permission notice as Musashi's in m68k_py.py (full text: emulator/Z80_LICENSE.txt).
# ---------------------------------------------------------------------------
try:                            # one-file build: M68K is defined above
    M68K
except NameError:
    from m68k_py import M68K

CPU_HZ = 12000000
LINE_CYCLES = 768
FRAME_LINES = 264
FRAME_CYCLES = LINE_CYCLES * FRAME_LINES
VIS_FIRST = 16
VIS_LINES = 224
VSSTART = 256
HOST_CLEAR = CPU_HZ // 1000
HOST_TIMEOUT = CPU_HZ * 3
HOST_WORDS = 2048
WDOG_CYCLES = 1622015
VBSTART = 0xF0
VBL_IRQ_AT = VBSTART * LINE_CYCLES + 29
TMR_RELOAD_AT = VBSTART * LINE_CYCLES + 573
H_IDLE, H_SENT, H_WAIT, H_DONE, H_TIMEOUT = range(5)
# The built-in test M1 (Z80 program; same bytes in neocore.c and in tools/make_test_cart.py's
# MAME bench cartridge). YM2610 SSG: port $04 = register, $05 = data; f = 125 kHz / period.
#   $0000 boot: di / ld sp,$ffff / xor a / out ($0c),a / out ($08),a (NMI on) / ei / idle: jp idle
#   $0066 NMI: in a,($00) / cp 3 / jp z,stop / cp 1 / jp nz,other / ld a,1 / out ($0c),a / retn
#   $0090 stop ($03): SSG mixer $3F (all off), volume A 0 / jp 0 (reboot: reply $00)
#   $00B0 other: $5C / $5D / $5E: beeps / $02: jingle / $7F: chime / else retn
#   $0100 / $0130 / $0160 beep ($5C left 1000 Hz, $5D right 1506 Hz, $5E centre 749 Hz): tone A
#         period, mixer $3E (tone A on), volume A 15 / retn: the tone lasts until the next command
#   $0200 jingle ($02, TestFM; stand-in for the eyecatcher music of a real M1): ld sp,$ffff /
#         C5 E5 G5 (120 ms each) C6 (214 ms): ld d,n / loop: ld b,0 / djnz $ / dec d / jr nz,loop /
#         then silence / jp idle
#   $0290 chime ($7F, TestSsg; stand-in for the coin chime of a real M1): as the jingle, 1984 Hz
#         (~54 ms) then 1563 Hz (~81 ms), then silence / jp idle
TEST_M1_PARTS = (
    (0x0000, bytes.fromhex("f331ffffafd30cd308fbc30a00")),
    (0x0066, bytes.fromhex("db00fe03ca9000fe01c2b0003e01d30ced45")),
    (0x0090, bytes.fromhex("3e07d3043e3fd3053e08d3043e00d305c30000")),
    (0x00B0, bytes.fromhex("fe5cca0001fe5dca3001fe5eca6001fe02ca0002fe7fca9002ed45")),
    (0x0100, bytes.fromhex("3e00d3043e7dd3053e01d3043e00d3053e07d3043e3ed3053e08d3043e0fd305ed45")),
    (0x0130, bytes.fromhex("3e00d3043e53d3053e01d3043e00d3053e07d3043e3ed3053e08d3043e0fd305ed45")),
    (0x0160, bytes.fromhex("3e00d3043ea7d3053e01d3043e00d3053e07d3043e3ed3053e08d3043e0fd305ed45")),
    (0x0200, bytes.fromhex(
        "31ffff3e07d3043e3ed3053e08d3043e0fd3053e00d3043eefd3053e01d3043e00d305168f060010fe1520f9"
        "3e00d3043ebed3053e01d3043e00d305168f060010fe1520f93e00d3043e9fd3053e01d3043e00d305168f06"
        "0010fe1520f93e00d3043e77d3053e01d3043e00d3051600060010fe1520f93e07d3043e3fd3053e08d3043e"
        "00d305c30a00")),
    (0x0290, bytes.fromhex(
        "31ffff3e07d3043e3ed3053e08d3043e0fd3053e00d3043e3fd3053e01d3043e00d3051640060010fe1520f9"
        "3e00d3043e50d3053e01d3043e00d3051660060010fe1520f93e07d3043e3fd3053e08d3043e00d305c30a00")),
)
CART_MAX = 0x1000000
MAX_FAULTS = 16


def _make_neo():
    bios = bytearray(0x20000)
    wram = bytearray(0x10000)
    pal = [0] * 0x2000
    vram = [0] * 0x10000
    vram_offset = vram_read_buffer = vram_modulo = 0
    latch = [0] * 8
    anim_speed = anim_disabled = anim_frame_counter = anim_counter = 0
    irq_vbl = irq_tmr = irq3 = tmr_ctrl = 0
    tmr_load = 0
    tmr_next = 0
    now_base = 0
    wdog_kick = 0
    wdog_enabled = 0
    wdog_resets = 0
    # Z80 side
    z80_mode = 1
    m1 = bytearray(b"\xff" * 0x10000)
    z80ram = bytearray(0x800)
    snd_latch = snd_pending = nmi_enable = nmi_line = 0
    z80_reply = 0
    z80_commands = 0
    z80_time = 0
    zpc = 0; zsp = 0xFFFF; za = 0xFF; zzf = 1; zb = zd = 0
    ziff1 = ziff2 = ziff_delay = zhalted = znmi = 0
    ssg = [0] * 16              # YM2610 SSG registers as the Z80 wrote them
    ssg_addr = 0
    ssg_writes = 0
    # host
    h_state = H_IDLE
    h_t0 = 0
    h_armed = 0
    h_clear_pending = 0
    h_values = [0] * HOST_WORDS
    h_count = h_overflow = 0
    h_done_cycles = 0
    watch = None                # extension checker hook (emu_host.ExtCheck): watch(offset, cycle)
    # faults: list of (region, kind, bit, value)
    faults = []
    # cartridge
    cart_mode = 0
    cart = bytearray(b"\xff" * CART_MAX)
    cart_size = cart_banks = cart_bank = 0
    cart_writes = cart_latch_writes = 0
    cart_hold = 0xFFFF
    float_rng = 0x2545F491
    # video
    line_colour = [0] * VIS_LINES
    frame_lines = [0] * VIS_LINES
    frames = 0
    last_line = 0
    in_exec = False
    # test-only inputs (build_test_core.py's neo_test_inputs)
    t_p1, t_dip, t_p2, t_sa, t_sb, t_sys, t_mvs = 0xFF, 0x00, 0xFF, 0x00, 0x7F, 0xFF00, 0
    t_bram = bytearray(0x10000)

    cpu = None
    # Opcode fetch fast path for the 68000 (m68k_py _build): FW = the BIOS as words, at their byte
    # offset; FAST[0] = 1 while no BIOS socket read has to be seen by the model.
    FW = [0] * 0x20000
    FAST = [1]

    def fw_sync(lo=0, hi=0x20000):
        for o in range(lo & ~1, hi, 2):
            FW[o] = (bios[o] << 8) | bios[o + 1]

    def upd_fast():
        # read16 reads the BIOS through socket_addr, which only region 5 (BIOS socket) faults change
        FAST[0] = 0 if (h_armed or watch or any(f[0] == 5 for f in faults)) else 1

    def fault_data(region, w):
        for r, k, b, v in faults:
            if r == region and k == 0:
                w = (w | (1 << b)) if v else (w & ~(1 << b))
        return w

    def sel_dead(region, a):
        # kind 4: the decoder of this region uses an address line it should ignore
        for r, k, b, v in faults:
            if r == region and k == 4 and ((a >> b) & 1) != v:
                return True
        return False

    def vectors_from_cart():
        for r, k, b, v in faults:
            if r == 7:
                return v
        return latch[1]

    def fault_addr(region, idx, shift):
        for r, k, b, v in faults:
            if r == region and k == 1:
                m = 1 << (b - shift)
                idx = (idx | m) if v else (idx & ~m)
        return idx

    def rng_bit():
        nonlocal float_rng
        x = float_rng
        x ^= (x << 13) & 0xFFFFFFFF
        x ^= x >> 17
        x ^= (x << 5) & 0xFFFFFFFF
        float_rng = x
        return x & 1

    def socket_addr(o):
        for r, k, b, v in faults:
            if r == 5:
                m = 1 << b
                if k == 3:
                    v = rng_bit()
                o = (o | m) if v else (o & ~m)
        return o & 0x1FFFE

    def slot_strobe_dead(s):
        for r, k, b, v in faults:
            if r == 6 and k == 2 and v == s:
                return True
        return False

    def slot_data(w):
        for r, k, b, v in faults:
            if r == 6 and k == 3:
                w = (w | (1 << b)) if rng_bit() else (w & ~(1 << b))
        return fault_data(6, w) & 0xFFFF

    def cart_read(a):
        if not cart_mode:
            return 0xFFFF
        p2 = a >= 0x200000
        o = fault_addr(6, a & 0xFFFFE, 0) & 0xFFFFE
        if cart_mode == 1:
            if p2 and not cart_banks:
                return slot_data(0xFFFF)
            o += (0x100000 + cart_bank * 0x100000) if p2 else 0
        w = (cart[o] << 8) | cart[o + 1]
        if faults:
            oe, h = (4, 8) if p2 else (2, 6)
            if slot_strobe_dead(oe):
                w = (w & 0xFF00) | (open_bus() & 0x00FF)
            if slot_strobe_dead(oe + 1):
                w = (w & 0x00FF) | (open_bus() & 0xFF00)
            if slot_strobe_dead(h):
                w = (w & 0xFF00) | (cart_hold & 0x00FF)
            if slot_strobe_dead(h + 1):
                w = (w & 0x00FF) | (cart_hold & 0xFF00)
        return slot_data(w)

    def cart_write(a, d, mask):
        nonlocal cart_writes, cart_hold, cart_latch_writes, cart_bank
        cart_writes += 1
        cart_hold = (cart_hold & ~mask) | (d & mask)
        if mask & 0x00FF:
            cart_latch_writes += 1
            if cart_mode == 1 and cart_banks:
                cart_bank = (slot_data(d) & 7) % cart_banks
        if cart_mode != 2:
            return
        o = fault_addr(6, a & 0xFFFFE, 0) & 0xFFFFE
        d = slot_data(d)
        if (mask & 0xFF00) and not slot_strobe_dead(1):
            cart[o] = (d >> 8) & 0xFF
        if (mask & 0x00FF) and not slot_strobe_dead(0):
            cart[o + 1] = d & 0xFF

    def lane_dead(lane):
        for r, k, b, v in faults:
            if r == 0 and k == 2 and v == lane:
                return True
        return False

    def now():
        return now_base + (cpu.cycles_run() if in_exec else 0)

    def pal_bank():
        return 0x1000 if latch[7] else 0

    def pal_index(a):
        return fault_addr(1, pal_bank() | ((a >> 1) & 0xFFF), 1) & 0x1FFF

    def wram_index(a):
        return fault_addr(0, a & 0xFFFF, 0) & 0xFFFE

    def vram_phys(v):
        if v & 0x8000:
            return 0x8000 | (fault_addr(3, v & 0x7FF, 0) & 0x7FF)
        return fault_addr(2, v & 0x7FFF, 0) & 0x7FFF

    def vram_read(v):
        if not faults:                           # = the line below with no fault
            return vram[(0x8000 | (v & 0x7FF)) if v & 0x8000 else (v & 0x7FFF)] & 0xFFFF
        return fault_data(3 if v & 0x8000 else 2, vram[vram_phys(v)]) & 0xFFFF

    def vpos_now():
        return (now() % FRAME_CYCLES) // LINE_CYCLES

    def video_control():
        v = vpos_now() + 0x100
        if v >= 0x200:
            v -= FRAME_LINES
        v = fault_data(4, v) & 0x1FF
        return ((v << 7) | (anim_counter & 7)) & 0xFFFF

    def open_bus():
        p = cpu.pc() & 0xFFFFFE
        if 0xC00000 <= p < 0xD00000:
            o = socket_addr(p & 0x1FFFE)
            return (bios[o] << 8) | bios[o + 1]
        return 0xFFFF

    # ---- Z80 (superzazu/z80 semantics for the opcodes the model's programs use)
    def zrb(a):
        return m1[a] if a < 0xF800 else z80ram[a - 0xF800]

    def zwb(a, v):
        if a >= 0xF800:
            z80ram[a - 0xF800] = v

    def update_nmi():
        nonlocal nmi_line, znmi
        line = 1 if (snd_pending and nmi_enable) else 0
        if line and not nmi_line:
            znmi = 1
        nmi_line = line

    def z_in(port):
        nonlocal snd_pending
        if port == 0x00:
            snd_pending = 0
            update_nmi()
            return snd_latch
        if 0x04 <= port <= 0x07:
            return 0
        if 0x08 <= (port & 0x0F) <= 0x0B:
            return 0
        return 0xFF

    def z_out(port, v):
        nonlocal snd_latch, nmi_enable, z80_reply, ssg_addr, ssg_writes
        if port == 0x04:                         # YM2610 address (port A)
            ssg_addr = v
            return
        if port == 0x05:                         # YM2610 data (port A): registers $00-$0F = SSG
            if ssg_addr < 0x10:
                ssg[ssg_addr] = v
                ssg_writes += 1
            return
        if port == 0x00:
            snd_latch = 0
            return
        if port == 0x08 or port == 0x18:
            nmi_enable = 1 if port == 0x08 else 0
            update_nmi()
            return
        if port == 0x0C:
            z80_reply = v

    def zpush(v):
        nonlocal zsp
        zsp = (zsp - 2) & 0xFFFF
        zwb(zsp, v & 0xFF)
        zwb((zsp + 1) & 0xFFFF, v >> 8)

    def znext():
        nonlocal zpc
        v = zrb(zpc)
        zpc = (zpc + 1) & 0xFFFF
        return v

    def znextw():
        lo = znext()
        return lo | (znext() << 8)

    def z80_step():
        """One z80_step(): an instruction (NOP when halted) then process_interrupts. Returns T-states."""
        nonlocal zpc, zsp, za, zzf, zb, zd, ziff1, ziff2, ziff_delay, zhalted, znmi
        if zhalted:
            cyc = 4
        else:
            op = znext()
            if op == 0xC3:                       # jp nn
                zpc = znextw(); cyc = 10
            elif op == 0xFF:                     # rst 38h
                zpush(zpc); zpc = 0x38; cyc = 11
            elif op == 0xDB:                     # in a,(n)
                za = z_in(znext()); cyc = 11
            elif op == 0xD3:                     # out (n),a
                z_out(znext(), za); cyc = 11
            elif op == 0xFE:                     # cp n (only Z is used by the programs)
                zzf = 1 if ((za - znext()) & 0xFF) == 0 else 0; cyc = 7
            elif op == 0xCA or op == 0xC2:       # jp z / jp nz
                t = znextw()
                if (zzf == 1) == (op == 0xCA):
                    zpc = t
                cyc = 10
            elif op == 0x3E:                     # ld a,n
                za = znext(); cyc = 7
            elif op == 0x31:                     # ld sp,nn
                zsp = znextw(); cyc = 10
            elif op == 0xAF:                     # xor a
                za = 0; zzf = 1; cyc = 4
            elif op == 0xF3:                     # di
                ziff1 = ziff2 = 0; cyc = 4
            elif op == 0xFB:                     # ei
                ziff_delay = 1; cyc = 4
            elif op == 0x00:
                cyc = 4
            elif op == 0x76:                     # halt
                zhalted = 1; cyc = 4
            elif op == 0x06:                     # ld b,n
                zb = znext(); cyc = 7
            elif op == 0x16:                     # ld d,n
                zd = znext(); cyc = 7
            elif op == 0x10:                     # djnz e
                e = znext(); zb = (zb - 1) & 0xFF; cyc = 8
                if zb:
                    zpc = (zpc + e - ((e & 0x80) << 1)) & 0xFFFF; cyc = 13
            elif op == 0x15:                     # dec d (only Z is used)
                zd = (zd - 1) & 0xFF; zzf = 1 if zd == 0 else 0; cyc = 4
            elif op == 0x20:                     # jr nz,e
                e = znext(); cyc = 7
                if not zzf:
                    zpc = (zpc + e - ((e & 0x80) << 1)) & 0xFFFF; cyc = 12
            elif op == 0xED:
                op2 = znext()
                if op2 == 0x45:                  # retn
                    ziff1 = ziff2
                    lo = zrb(zsp); hi = zrb((zsp + 1) & 0xFFFF)
                    zsp = (zsp + 2) & 0xFFFF
                    zpc = lo | (hi << 8)
                    cyc = 14
                else:
                    raise RuntimeError(f"Z80 opcode ED {op2:02X} not modelled (pc {zpc:04X})")
            else:
                raise RuntimeError(f"Z80 opcode {op:02X} not modelled (pc {(zpc - 1) & 0xFFFF:04X})")
        # process_interrupts
        if ziff_delay > 0:
            ziff_delay -= 1
            if ziff_delay == 0:
                ziff1 = ziff2 = 1
            return cyc
        if znmi:
            znmi = 0
            zhalted = 0
            ziff1 = 0
            cyc += 11
            zpush(zpc)
            zpc = 0x66
        return cyc

    def z80_reset():
        nonlocal zpc, zsp, za, zzf, zb, zd, ziff1, ziff2, ziff_delay, zhalted, znmi, snd_pending, nmi_enable, nmi_line
        nonlocal z80_reply, ssg_addr
        zpc = 0; zsp = 0xFFFF; za = 0xFF; zzf = 1; zb = zd = 0
        ziff1 = ziff2 = ziff_delay = zhalted = znmi = 0
        snd_pending = nmi_enable = nmi_line = 0
        z80_reply = 0
        ssg[:] = [0] * 16          # the YM2610 is reset with the console (/IC on the reset line)
        ssg_addr = 0

    def z80_load_program():
        m1[:] = b"\xff" * 0x10000
        if z80_mode == 1:
            for a, b in TEST_M1_PARTS:
                m1[a:a + len(b)] = b

    def z80_sync():
        nonlocal z80_time, zsp
        target = now() // 3
        while z80_time < target:
            # idle loops, run in one go (same result as stepping: nothing else can happen in them)
            if not znmi and not ziff_delay and not zhalted:
                if zpc == 0x0A and m1[0x0A] == 0xC3 and m1[0x0B] == 0x0A and m1[0x0C] == 0x00:
                    n = (target - z80_time + 9) // 10            # jp $000A
                    z80_time += 10 * n
                    return
                if zpc == 0x38 and m1[0x38] == 0xFF:            # rst 38h at $38: the stack only moves
                    n = (target - z80_time + 10) // 11
                    z80_time += 11 * n
                    for _ in range(min(n, 0x8000)):            # stack writes land in RAM as stepping does
                        zpush(0x39)
                    if n > 0x8000:
                        zsp = (zsp - 2 * (n - 0x8000)) & 0xFFFF
                    return
            z80_time += z80_step()

    def z80_command(c):
        nonlocal z80_commands, snd_latch, snd_pending
        z80_sync()
        z80_commands += 1
        snd_latch = c
        snd_pending = 1
        update_nmi()

    def vram_set_offset(d):
        nonlocal vram_offset, vram_read_buffer
        vram_offset = (d & 0x87FF) if (d & 0x8000) else d
        vram_read_buffer = vram_read(vram_offset)

    def vram_write(d):
        v = vram_offset
        vram[((0x8000 | (v & 0x7FF)) if v & 0x8000 else (v & 0x7FFF)) if not faults else vram_phys(v)] = d & 0xFFFF
        vram_set_offset((vram_offset & 0x8000) | ((vram_offset + vram_modulo) & 0x7FFF))

    def host_port_read(o):
        nonlocal h_armed, h_count, h_overflow, h_state, h_done_cycles
        if watch:
            watch(o, now())
            if o < 0xA0 and not h_armed:        # a command block read, seen only because of the hook
                return
        if h_armed:
            h_armed -= 1
            if h_armed:
                return
            upd_fast()
            if h_state == H_SENT or h_state == H_WAIT:
                h_values[h_count % HOST_WORDS] = (o >> 1) & 0xFFFF
                h_count += 1
                if h_count >= HOST_WORDS:
                    h_overflow = 1
            return
        if o == 0x1FF02:
            h_armed = 2
            FAST[0] = 0
            return
        if o == 0x1FF00:
            if h_state == H_SENT or h_state == H_WAIT:
                h_state = H_DONE
                h_done_cycles = now() - h_t0

    # ---- 16-bit bus
    def read16(a, lsb_only=0):
        a &= 0xFFFFFE
        if 0xC00000 <= a < 0xD00000:                                  # BIOS socket (most accesses)
            o = socket_addr(a & 0x1FFFE) if faults else (a & 0x1FFFE)
            if h_armed or o == 0x1FF02 or o == 0x1FF00 or (o < 0xA0 and watch):
                host_port_read(o)
            return (bios[o] << 8) | bios[o + 1]
        if a < 0x000080:
            if vectors_from_cart():
                return cart_read(a)
            o = socket_addr(a)
            if h_armed or o == 0x1FF02 or o == 0x1FF00:
                host_port_read(o)
            return (bios[o] << 8) | bios[o + 1]
        if a < 0x100000:
            return cart_read(a)
        if a < 0x200000:
            if not faults:
                o = a & 0xFFFE
                return (wram[o] << 8) | wram[o + 1]
            if sel_dead(0, a):
                return open_bus()
            o = wram_index(a)
            w = (wram[o] << 8) | wram[o + 1]
            if lane_dead(1):
                w |= 0xFF00
            if lane_dead(0):
                w |= 0x00FF
            return fault_data(0, w)
        if a < 0x300000:
            return cart_read(a)
        if a < 0x320000:
            return t_sys if a == 0x300080 else ((t_p1 << 8) | t_dip)
        if a < 0x340000:
            z80_sync()
            return (z80_reply << 8) | t_sa
        if a < 0x360000:
            return t_p2 << 8
        if a < 0x380000:
            return open_bus()
        if a < 0x3A0000:
            return (t_sb << 8) | 0xFF
        if a < 0x3C0000:
            return open_bus()
        if a < 0x3E0000:
            if faults and sel_dead(8, a):
                return open_bus()
            if lsb_only:
                return open_bus() & 0xFF
            r = (a >> 1) & 3
            if r < 2:
                return vram_read_buffer
            if r == 2:
                return vram_modulo
            return video_control()
        if a < 0x400000:
            return open_bus()
        if a < 0x800000:
            if faults and sel_dead(1, a):
                return open_bus()
            return fault_data(1, pal[pal_index(a)]) & 0xFFFF
        if a < 0xC00000:
            return 0xFFFF
        if t_mvs and a < 0xD10000:
            return (t_bram[a & 0xFFFE] << 8) | t_bram[(a & 0xFFFE) + 1]
        return open_bus()

    def write16(a, d, mask=0xFFFF):
        nonlocal cart_hold, wdog_kick, vram_modulo, anim_speed, anim_disabled, tmr_ctrl, tmr_load
        nonlocal irq3, irq_tmr, irq_vbl
        a &= 0xFFFFFE
        if 0x100000 <= a < 0x200000:
            if not faults:
                o = a & 0xFFFE
                if mask & 0xFF00:
                    wram[o] = (d >> 8) & 0xFF
                if mask & 0x00FF:
                    wram[o + 1] = d & 0xFF
                return
            if sel_dead(0, a):
                return
            o = wram_index(a)
            if (mask & 0xFF00) and not lane_dead(1):
                wram[o] = (d >> 8) & 0xFF
            if (mask & 0x00FF) and not lane_dead(0):
                wram[o + 1] = d & 0xFF
            for r, k, b, v in faults:                 # kind 5: the WRAM write strobe also reaches the palette RAM
                if r == 0 and k == 5:
                    i = pal_index(a)
                    pal[i] = ((pal[i] & ~mask) | (d & mask)) & 0xFFFF
                    break
            return
        if a < 0x100000:
            cart_hold = (cart_hold & ~mask) | (d & mask)
            return
        if a < 0x300000:
            cart_write(a, d, mask)
            return
        if a < 0x320000:
            if mask & 0x00FF:
                wdog_kick = now()
            return
        if a < 0x340000:
            if mask & 0xFF00:
                z80_command((d >> 8) & 0xFF)
            return
        if 0x3A0000 <= a < 0x3C0000:
            if mask & 0x00FF:
                off = (a >> 1) & 0xF
                latch[off & 7] = (off & 8) >> 3
            return
        if 0x3C0000 <= a < 0x3E0000:
            if faults and sel_dead(8, a):
                return
            r = (a >> 1) & 7
            if r == 0:
                vram_set_offset(d & 0xFFFF)
            elif r == 1:
                vram_write(d & 0xFFFF)
            elif r == 2:
                vram_modulo = d & 0xFFFF
            elif r == 3:
                anim_speed = (d >> 8) & 0xFF
                anim_disabled = (d >> 3) & 1
                tmr_ctrl = d & 0xF0
            elif r == 4:
                tmr_load = (tmr_load & 0x0000FFFF) | ((d & 0xFFFF) << 16)
            elif r == 5:
                tmr_load = (tmr_load & 0xFFFF0000) | (d & 0xFFFF)
                if tmr_ctrl & 0x20:
                    tmr_arm(now())
            elif r == 6:
                if d & 1:
                    irq3 = 0
                if d & 2:
                    irq_tmr = 0
                if d & 4:
                    irq_vbl = 0
                update_irq()
            return
        if 0x400000 <= a < 0x800000:
            if faults and sel_dead(1, a):
                return
            i = pal_index(a)
            pal[i] = ((pal[i] & ~mask) | (d & mask)) & 0xFFFF
            return
        if t_mvs and 0xD00000 <= a < 0xD10000:
            if mask & 0xFF00:
                t_bram[a & 0xFFFE] = (d >> 8) & 0xFF
            if mask & 0x00FF:
                t_bram[(a & 0xFFFE) + 1] = d & 0xFF
            return
        # ROM, cartridge, memory card, unmapped: ignored

    def bus8(a):
        w = read16(a, a & 1)
        return (w & 0xFF) if (a & 1) else (w >> 8)

    def wbus8(a, v):
        nonlocal wdog_kick
        if a == 0x300001:                        # WatchDog macro (move.b d0,$300001): most byte writes
            wdog_kick = now()
            return
        if 0x400000 <= a < 0x800000:
            write16(a & ~1, (v & 0xFF) * 0x0101, 0xFFFF)
            return
        if a & 1:
            write16(a, v & 0xFF, 0x00FF)
        else:
            write16(a, (v & 0xFF) << 8, 0xFF00)

    def update_irq():
        cpu.set_irq(3 if irq3 else 2 if irq_tmr else 1 if irq_vbl else 0)

    def tmr_arm(t):
        nonlocal tmr_next
        tmr_next = t + 2 * (tmr_load + 1)

    def frame_event(t, at):
        f = t // FRAME_CYCLES * FRAME_CYCLES + at
        return f if f >= t else f + FRAME_CYCLES

    def reset_peripherals():
        nonlocal cart_bank, z80_time
        latch[:] = [0] * 8
        cart_bank = 0
        z80_reset()
        z80_time = now() // 3

    def line_event(line_abs):
        nonlocal anim_frame_counter, anim_counter, frames
        vpos = line_abs % FRAME_LINES
        if VIS_FIRST <= vpos < VIS_FIRST + VIS_LINES:
            line_colour[vpos - VIS_FIRST] = fault_data(1, pal[fault_addr(1, pal_bank() | 0xFFF, 1) & 0x1FFF]) & 0xFFFF
        if vpos == VSSTART:
            if anim_frame_counter == 0:
                anim_frame_counter = anim_speed
                anim_counter = (anim_counter + 1) & 0xFF
            else:
                anim_frame_counter -= 1
        if vpos == 0:
            frame_lines[:] = line_colour
            frames = (frames + 1) & 0xFFFFFFFF

    def host_update():
        nonlocal h_clear_pending, h_state
        t = now()
        if h_clear_pending and t - h_t0 >= HOST_CLEAR:
            bios[0x90:0xA0] = bytes(16)
            fw_sync(0x90, 0xA0)
            h_clear_pending = 0
            if h_state == H_SENT:
                h_state = H_WAIT
        if (h_state == H_SENT or h_state == H_WAIT) and t - h_t0 >= HOST_TIMEOUT:
            h_state = H_TIMEOUT

    # ---- API
    def neo_version():
        return 1

    def neo_load_bios(data, length=None):
        n = len(data) if length is None else length
        if n <= 0 or n > len(bios):
            return -1
        bios[:] = b"\xff" * len(bios)
        bios[:n] = bytes(data[:n])
        fw_sync()
        return 0

    def neo_power_on():
        nonlocal vram_offset, vram_read_buffer, vram_modulo, anim_speed, anim_disabled, anim_frame_counter
        nonlocal anim_counter, h_state, h_count, h_overflow, h_armed, h_clear_pending, now_base, last_line
        nonlocal frames, wdog_resets, irq_vbl, irq_tmr, irq3, tmr_ctrl, tmr_load, tmr_next, wdog_kick, ssg_writes
        ssg_writes = 0                              # SSG write count: since power on
        wram[:] = bytes(0x10000)
        pal[:] = [0] * 0x2000
        vram[:] = [0] * 0x10000
        vram_offset = vram_read_buffer = vram_modulo = 0
        anim_speed = anim_disabled = anim_frame_counter = anim_counter = 0
        line_colour[:] = [0] * VIS_LINES
        frame_lines[:] = [0] * VIS_LINES
        z80ram[:] = bytes(0x800)
        z80_load_program()
        h_state = H_IDLE; h_count = 0; h_overflow = 0; h_armed = 0; h_clear_pending = 0
        upd_fast()
        now_base = 0; last_line = 0; frames = 0; wdog_resets = 0
        irq_vbl = irq_tmr = 0; irq3 = 1; tmr_ctrl = 0; tmr_load = 0; tmr_next = 0
        reset_peripherals()
        cpu.pulse_reset()
        update_irq()
        wdog_kick = 0

    def neo_reset():
        nonlocal h_state, h_clear_pending, wdog_kick
        reset_peripherals()
        h_state = H_IDLE
        if h_clear_pending:
            bios[0x90:0xA0] = bytes(16)
            fw_sync(0x90, 0xA0)
            h_clear_pending = 0
        cpu.pulse_reset()
        update_irq()
        wdog_kick = now()

    def neo_set_options(z80, watchdog):
        nonlocal z80_mode, wdog_enabled
        if z80 != z80_mode:
            z80_mode = z80
            z80_load_program()
            reset_peripherals()
        wdog_enabled = watchdog

    def neo_run(cycles):
        nonlocal now_base, in_exec, irq_vbl, irq_tmr, tmr_next, last_line, wdog_resets
        end = now_base + cycles
        execute = cpu.execute
        while now_base < end:
            next_line = (now_base // LINE_CYCLES + 1) * LINE_CYCLES
            stop = next_line if next_line < end else end
            ev_vbl = frame_event(now_base, VBL_IRQ_AT)
            ev_rl = frame_event(now_base, TMR_RELOAD_AT)
            if ev_vbl == now_base:
                ev_vbl += FRAME_CYCLES
            if ev_rl == now_base:
                ev_rl += FRAME_CYCLES
            if ev_vbl < stop:
                stop = ev_vbl
            if ev_rl < stop:
                stop = ev_rl
            if tmr_next and now_base < tmr_next < stop:
                stop = tmr_next
            if h_clear_pending and now_base < h_t0 + HOST_CLEAR < stop:
                stop = h_t0 + HOST_CLEAR
            before = now_base
            in_exec = True
            used = execute(stop - now_base)
            in_exec = False
            now_base += used
            changed = False
            if frame_event(before + 1, VBL_IRQ_AT) <= now_base:
                irq_vbl = 1
                changed = True
            r = frame_event(before + 1, TMR_RELOAD_AT)
            if r <= now_base and (tmr_ctrl & 0x40):
                tmr_arm(r)
            while tmr_next and tmr_next <= now_base:
                if tmr_ctrl & 0x10:
                    irq_tmr = 1
                    changed = True
                if tmr_ctrl & 0x80:
                    tmr_arm(tmr_next)
                else:
                    tmr_next = 0
            if changed:
                update_irq()
            while (last_line + 1) * LINE_CYCLES <= now_base:
                last_line = (last_line + 1) & 0xFFFFFFFF
                line_event(last_line)
            host_update()
            z80_sync()
            if wdog_enabled and now_base - wdog_kick > WDOG_CYCLES:
                wdog_resets += 1
                neo_reset()

    def neo_run_frame():
        neo_run(FRAME_CYCLES)

    def neo_host_send(addr, p1, p2, p3):
        nonlocal h_count, h_overflow, h_armed, h_t0, h_state, h_clear_pending
        if h_state == H_SENT or h_state == H_WAIT or h_clear_pending:
            return -1
        for i, v in enumerate((addr, p1, p2, p3)):
            bios[0x90 + 4 * i:0x94 + 4 * i] = (v & 0xFFFFFFFF).to_bytes(4, "big")
        fw_sync(0x90, 0xA0)
        h_count = 0; h_overflow = 0; h_armed = 0
        upd_fast()
        h_t0 = now_base
        h_state = H_SENT
        h_clear_pending = 1
        return 0

    def neo_host_state():
        return h_state

    def neo_host_values(out, maxn):
        n = h_count % HOST_WORDS
        if n > maxn:
            n = maxn
        base = h_count - (h_count % HOST_WORDS)
        for i in range(n):
            out[i] = h_values[(base + i) % HOST_WORDS]
        return n

    def neo_host_overflow():
        return h_overflow

    def neo_host_cycles():
        return h_done_cycles & 0xFFFFFFFF

    def neo_host_ack():
        nonlocal h_state
        if h_state == H_DONE or h_state == H_TIMEOUT:
            h_state = H_IDLE

    def neo_get_lines(out):
        out[:VIS_LINES] = frame_lines

    def neo_get_vram(out):
        if not faults:
            out[:0x8800] = vram[:0x8800]
        else:
            out[:0x8800] = [vram_read(v) for v in range(0x8800)]

    def neo_get_palette(out):
        if not faults:
            b = pal_bank()
            out[:0x1000] = pal[b:b + 0x1000]
        else:
            out[:0x1000] = [fault_data(1, pal[pal_index(i << 1)]) & 0xFFFF for i in range(0x1000)]

    def neo_cart_load(mode, data, length=None):
        nonlocal cart_mode, cart_size, cart_banks, cart_bank, cart_writes, cart_latch_writes, cart_hold
        n = (len(data) if data else 0) if length is None else length
        if mode < 0 or mode > 2 or n < 0 or n > CART_MAX:
            return -1
        if mode == 1 and (n < 0x100000 or (n & 0xFFFFF)):
            return -1
        if mode == 2 and n > 0x100000:
            return -1
        cart_mode = mode
        cart[:] = b"\xff" * CART_MAX
        cart_size = n
        if data and n:
            cart[:n] = bytes(data[:n])
        cart_banks = (cart_size - 0x100000) // 0x100000 if mode == 1 else 0
        cart_bank = 0
        cart_writes = cart_latch_writes = 0
        cart_hold = 0xFFFF
        return 0

    def neo_fault_clear():
        faults.clear()
        upd_fast()

    def neo_fault_add(region, kind, bit, value):
        data_bits = (15, 15, 15, 15, 8, -1, 15, 0, -1)
        addr_lo = (1, 1, 0, 0, -1, 1, 1, -1, -1)
        addr_hi = (15, 13, 14, 10, -1, 16, 19, -1, -1)
        sel_lo = (16, 13, 0, 0, 0, 0, 0, 0, 4)
        sel_hi = (19, 21, -1, -1, -1, -1, -1, -1, 16)
        if kind < 0 or kind > 5 or len(faults) >= MAX_FAULTS or region < 0 or region > 8:
            return -1
        if region == 7 and kind != 0:
            return -1
        if region == 8 and kind != 4:
            return -1
        if kind == 4 and (bit < sel_lo[region] or bit > sel_hi[region]):
            return -1
        if kind == 5 and (region != 0 or bit != 0 or value != 1):
            return -1
        if value < 0 or value > (9 if (region == 6 and kind == 2) else 1):
            return -1
        if kind == 0 and (bit < 0 or bit > data_bits[region]):
            return -1
        if kind == 1 and (addr_lo[region] < 0 or bit < addr_lo[region] or bit > addr_hi[region]):
            return -1
        if kind == 2 and region != 0 and region != 6:
            return -1
        if kind == 3 and region == 5 and (bit < 1 or bit > 16):
            return -1
        if kind == 3 and region == 6 and (bit < 0 or bit > 15):
            return -1
        if kind == 3 and region != 5 and region != 6:
            return -1
        faults.append((region, kind, bit, value))
        upd_fast()
        return 0

    def neo_ssg_regs(out):
        """The 16 YM2610 SSG registers into out[0..15]; returns the count of SSG register writes."""
        out[:16] = ssg
        return ssg_writes & 0xFFFFFFFF

    def neo_watch(fn):
        """Python core only: fn(offset, cycle) on every read of the host ports ($1FF00 / $1FF02 and the
        armed reads after them) and of the command block $90-$9F; None to stop."""
        nonlocal watch
        watch = fn
        upd_fast()

    def neo_test_inputs(p1, dip, p2, sa, sb, sys_, mvs):
        """Test hook (as build_test_core.py's core): input ports, MVS backup RAM."""
        nonlocal t_p1, t_dip, t_p2, t_sa, t_sb, t_sys, t_mvs
        t_p1, t_dip, t_p2, t_sa, t_sb, t_sys, t_mvs = p1, dip, p2, sa, sb, sys_, mvs

    api = dict(
        neo_version=neo_version, neo_load_bios=neo_load_bios, neo_power_on=neo_power_on, neo_reset=neo_reset,
        neo_set_options=neo_set_options, neo_run=neo_run, neo_run_frame=neo_run_frame,
        neo_host_send=neo_host_send, neo_host_state=neo_host_state, neo_host_values=neo_host_values,
        neo_host_overflow=neo_host_overflow, neo_host_cycles=neo_host_cycles, neo_host_ack=neo_host_ack,
        neo_get_lines=neo_get_lines, neo_get_vram=neo_get_vram, neo_get_palette=neo_get_palette,
        neo_frames=lambda: frames, neo_pc=lambda: cpu.pc(), neo_reg=lambda r: cpu.get_reg(r),
        neo_cycles=lambda: now_base, neo_watchdog_resets=lambda: wdog_resets,
        neo_z80_commands=lambda: z80_commands, neo_z80_pc=lambda: zpc,
        neo_ssg_regs=neo_ssg_regs,
        neo_peek16=lambda a: read16(a & 0xFFFFFFFF, 0) & 0xFFFF,
        neo_cart_load=neo_cart_load, neo_cart_bank=lambda: cart_bank, neo_cart_writes=lambda: cart_writes,
        neo_cart_latch_writes=lambda: cart_latch_writes, neo_fault_clear=neo_fault_clear,
        neo_fault_count=lambda: len(faults), neo_fault_add=neo_fault_add, neo_test_inputs=neo_test_inputs, neo_watch=neo_watch)

    def attach(c):
        nonlocal cpu
        cpu = c

    return api, attach, read16, bus8, write16, wbus8, (FAST, FW)


class PyNeoLib:
    """The neocore.c API in Python: lib.neo_xxx(...) as with the ctypes library."""

    def __init__(self):
        api, attach, bus16, bus8, wbus16, wbus8, fast = _make_neo()
        attach(M68K(bus16, bus8, wbus16, wbus8, fast=fast))
        self.__dict__.update(api)

# ===========================================================================
# emu_host.py: Core loader + host
# ===========================================================================
# ---------------------------------------------------------------------------
# Core loader + Brico16Bits-like host (shared by the window and --run)
# ---------------------------------------------------------------------------
import ctypes
import re
import struct

try:                            # one-file build: the Python core is inlined above
    PyNeoLib
except NameError:
    from neo_py import PyNeoLib

FRAME_CYCLES = 202752
CPU_HZ = 12000000
H_IDLE, H_SENT, H_WAIT, H_DONE, H_TIMEOUT = range(5)
TYPE_VOID, TYPE_WORD, TYPE_STRING, TYPE_DUMP = range(4)
TYPE_NAMES = {TYPE_VOID: "void", TYPE_WORD: "word", TYPE_STRING: "text", TYPE_DUMP: "dump"}


class Core:
    def __init__(self, lib_path=None):
        """lib_path None: the built-in Python core (PyNeoLib); else a C core library (neocore.c)."""
        self.kind = "python" if lib_path is None else "C"
        self.cart = None
        self._vals = (ctypes.c_uint16 * 2048)()
        self._lines = (ctypes.c_uint16 * 224)()
        self._vram = (ctypes.c_uint16 * 0x8800)()
        self._pal = (ctypes.c_uint16 * 0x1000)()
        self._ssg = (ctypes.c_uint16 * 16)()
        if lib_path is None:
            self.lib = PyNeoLib()
            return
        self.lib = lib = ctypes.CDLL(str(lib_path))
        lib.neo_version.restype = ctypes.c_int
        lib.neo_load_bios.argtypes = [ctypes.c_char_p, ctypes.c_int]
        lib.neo_run.argtypes = [ctypes.c_uint32]
        lib.neo_host_send.argtypes = [ctypes.c_uint32] * 4
        lib.neo_host_values.argtypes = [ctypes.POINTER(ctypes.c_uint16), ctypes.c_int]
        lib.neo_host_cycles.restype = ctypes.c_uint32
        lib.neo_get_lines.argtypes = [ctypes.POINTER(ctypes.c_uint16)]
        lib.neo_get_vram.argtypes = [ctypes.POINTER(ctypes.c_uint16)]
        lib.neo_get_palette.argtypes = [ctypes.POINTER(ctypes.c_uint16)]
        lib.neo_frames.restype = ctypes.c_uint32
        lib.neo_pc.restype = ctypes.c_uint32
        lib.neo_cycles.restype = ctypes.c_uint64
        lib.neo_set_options.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.neo_peek16.argtypes = [ctypes.c_uint32]
        lib.neo_peek16.restype = ctypes.c_uint16
        lib.neo_z80_commands.restype = ctypes.c_uint32
        lib.neo_fault_add.argtypes = [ctypes.c_int] * 4
        lib.neo_fault_add.restype = ctypes.c_int
        lib.neo_cart_load.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int]
        lib.neo_cart_load.restype = ctypes.c_int
        lib.neo_cart_writes.restype = ctypes.c_uint32
        lib.neo_cart_latch_writes.restype = ctypes.c_uint32
        lib.neo_cart_bank.restype = ctypes.c_int
        lib.neo_ssg_regs.restype = ctypes.c_uint32

    def load(self, rom):
        if self.lib.neo_load_bios(rom, len(rom)) != 0:
            raise ValueError("ROM larger than 128 KB")

    def load_cart(self, cart):
        """cart: None, 'none', 'test', 'diag' or a CartImage (see load_cartridge). Like a real
        cartridge it stays in across power cycles; insert it with the console off."""
        if isinstance(cart, str) or cart is None:
            cart = make_cart(cart or "none")
        data = cart.data or None
        if self.lib.neo_cart_load(cart.mode, data, len(cart.data)) != 0:
            raise ValueError(f"cartridge refused by the core ({len(cart.data)} bytes)")
        self.cart = cart

    def power_on(self):
        self.lib.neo_power_on()

    def ssg(self):
        """(16 YM2610 SSG registers as the Z80 wrote them, count of SSG writes)."""
        n = self.lib.neo_ssg_regs(self._ssg)
        return list(self._ssg), n

    def lines(self):
        self.lib.neo_get_lines(self._lines)
        return list(self._lines)

    def layer_state(self):
        """Reads VRAM and the palette as the display sees them; returns a checksum of what the
        tile layers depend on (redraw only when it changes)."""
        import zlib
        self.lib.neo_get_vram(self._vram)
        self.lib.neo_get_palette(self._pal)
        return zlib.crc32(bytes(self._pal), zlib.crc32(bytes(self._vram))) ^ id(self.cart)

    def layers(self):
        """Fix layer and sprites from the last layer_state(): 224 rows of 320 colour words or None
        (backdrop). See render_layers for what is and is not drawn."""
        return render_layers(self._vram, self._pal, self.cart.tiles if self.cart else None)

    def screen(self):
        """The whole picture: 224 rows of 320 colour words, tile layers over the backdrop lines."""
        self.layer_state()
        lines = self.lines()
        return [[lines[y] if c is None else c for c in row] for y, row in enumerate(self.layers())]


def parse_extensions(rom):
    """[(name, address, type, description)] from the BricoNeo table at $A0."""
    exts, off = [], 0xA0
    for _ in range(200):
        addr, typ = struct.unpack_from(">IH", rom, off)
        if addr == 0xFFFFFFFF:
            return exts
        off += 6
        end = rom.index(b"\0", off); name = rom[off:end].decode("latin-1"); off = end + 1 + ((end + 1) & 1)
        end = rom.index(b"\0", off); desc = rom[off:end].decode("latin-1"); off = end + 1 + ((end + 1) & 1)
        exts.append((name, addr, typ, desc))
    raise ValueError("extension table without end marker")


def parse_uint(text):
    """Same rules as Brico16Bits Command::ParseUint: $hex, 0xhex or decimal."""
    t = text.strip()
    try:
        if t.startswith("$"):
            return int(t[1:], 16) & 0xFFFFFFFF
        if t.lower().startswith("0x"):
            return int(t, 16) & 0xFFFFFFFF
        return int(t) & 0xFFFFFFFF
    except ValueError:
        m = re.match(r"\d+", t)            # sscanf("%d") stops at the first non-digit
        return int(m.group()) if m else 0


EXC_NAMES = {2: "bus error", 3: "address error", 4: "illegal instruction", 5: "divide by zero", 6: "CHK",
             7: "TRAPV", 8: "privilege violation", 10: "line A opcode", 11: "line F opcode",
             24: "unexpected interrupt"}


def format_exception(typ, values):
    """Brico16Bits (local branch workspace/nicolas-exceptions): a 68000 exception ends the output with
    the 68k command EXCPT + 6 words; the output before it is shown as usual, then the report
    (CommandExtension + Command68kException). None when the output does not end with a report."""
    if len(values) < 11 or any((values[-11 + i] != ord(ch)) for i, ch in enumerate("EXCPT")):
        return None
    v = values[-6:]
    txt = format_result(typ, values[:-11]) if len(values) > 11 else ""
    txt += (f"\n*** 68000 exception: {EXC_NAMES.get(v[0], 'reserved vector')} (vector {v[0]}) "
            f"at PC ${(v[2] << 16) | v[3]:06x}, SR ${v[1]:04x}")
    if v[0] in (2, 3):
        txt += f", access ${(v[4] << 16) | v[5]:06x}"
    return txt + " ***\n(PC/SR are read from the exception frame in work RAM)\n" \
        "[Extension aborted by a 68000 exception]\n"


def format_result(typ, values):
    """Text as Brico16Bits DisplayResult shows it."""
    if typ == TYPE_VOID:
        return ""
    if typ == TYPE_WORD:
        return f"0x{values[0]:04x}\n" if values else "[Empty]\n"
    if typ == TYPE_STRING:
        return "".join(chr(v & 0xFF) for v in values if v & 0xFF) + "\n"
    if typ == TYPE_DUMP:
        if len(values) < 2:
            return "[Empty]\n"
        base = values[0] | (values[1] << 16)
        out = [f"Memory content starting at address 0x{base:06x}:"]
        data = values[2:]
        for i in range(0, len(data), 8):
            row = data[i:i + 8]
            words = "".join(f"{w:04x} " for w in row) + "     " * (8 - len(row))
            chars = "".join((chr(c) if 32 <= c < 128 else ".") for w in row for c in (w >> 8, w & 0xFF))
            out.append(f"{base + 2 * i:06x}: {words} | {chars}")
        return "\n".join(out) + "\n"
    return f"Wrong return type sent by host ({typ})\n"


class Host:
    """Brico16Bits host on top of the core: commands by name, 1 ms clear, 3 s timeout."""

    def __init__(self, core, rom):
        self.core = core
        self.rom = rom
        self.exts = parse_extensions(rom)
        self.by_name = {n.lower(): (n, a, t, d) for n, a, t, d in self.exts}
        self.pending = None
        self.last_values = []           # output words of the last finished command

    def find(self, name):
        return self.by_name.get(name.lower())

    def start(self, line):
        """Starts a command line ("TestDAC 1", "Dump $100000 8"). Returns an error text or None."""
        parts = line.split()
        if not parts:
            return "Empty command"
        ext = self.find(parts[0])
        if ext is None:
            return f"Unknown command: {parts[0]} (type Help)"
        params = [parse_uint(p) for p in parts[1:4]] + [0, 0, 0]
        if self.core.lib.neo_host_send(ext[1], params[0], params[1], params[2]) != 0:
            return "Busy: the previous command is still running"
        self.pending = ext
        return None

    def poll(self):
        """None while running, else (status, text, seconds)."""
        st = self.core.lib.neo_host_state()
        if st in (H_SENT, H_WAIT) or self.pending is None:
            return None
        n = self.core.lib.neo_host_values(self.core._vals, 2048)
        values = list(self.core._vals[:n])
        secs = self.core.lib.neo_host_cycles() / CPU_HZ
        self.core.lib.neo_host_ack()
        name, _, typ, _ = self.pending
        self.pending = None
        self.last_values = values
        if st == H_TIMEOUT:
            return "timeout", "[Timeout]\n", 3.0
        exc = format_exception(typ, values)
        if exc:
            return "exception", exc, secs
        text = format_result(typ, values)
        if self.core.lib.neo_host_overflow():
            text += ("[More than 2047 words: the BricoNeo ring buffer wrapped, only the last words are left "
                     "(Brico16Bits InputBuffer, 2048 words)]\n")
        return "eot", text, secs

    def run_blocking(self, line, max_frames=400):
        err = self.start(line)
        if err:
            return "error", err + "\n", 0.0
        for _ in range(max_frames):
            self.core.lib.neo_run_frame()
            r = self.poll()
            if r:
                return r
        return "timeout", "[Timeout]\n", 3.0


# ---------------------------------------------------------------------------
# Extension checker: the Brico16Bits rules a new extension must follow, checked on the bus
# ---------------------------------------------------------------------------
CHECK_LONG = 1.5                 # s: half the BricoNeo 3 s timeout
CHECK_POLL_WARN = 0.75e-3        # s: after the EOT, BRICO_COMMAND_IN read less often than this: little margin
CHECK_POLL_FAIL = 1e-3           # s: the BricoNeo holds a command 1 ms: a longer gap can miss one
CHECK_AFTER = 0.1                # s watched after the EOT
CHECK_RESEND = 20e-6             # s: loop mode (*Command) resends this long after the EOT and the 1 ms clear
                                 # (assumed Brico16Bits latency: not measured on a real BricoNeo)


class ExtCheck:
    """Watches one command on the Python core (neo_watch hook) and lists what breaks the Brico16Bits
    rules: output with interrupts on or from RAM, P1-P3 read after the 1 ms clear, no EOT or two,
    output after the EOT, more than 2047 words, a result that does not fit the declared type, a run
    close to the 3 s timeout, a watchdog reset, no polling of the next command after the EOT.
    Usage: check_command(host, line), or chk.begin(); run; chk.after(); chk.end(...)"""

    def __init__(self, core):
        self.lib = core.lib
        self.ok = hasattr(core.lib, "neo_watch")       # the C core has no hook

    def begin(self):
        self.arm = 0
        self.out_irq = self.out_ram = self.late_param = None
        self.eot = None
        self.eots = self.after_eot = 0
        self.last_poll = None
        self.gap = 0
        self.wd0 = self.lib.neo_watchdog_resets()
        self.wd_before_eot = 0
        if self.ok:
            self.lib.neo_watch(self._on)

    def _on(self, o, t):
        L = self.lib
        if self.arm:                                   # the 2 reads after $1FF02 (mirrors the core)
            self.arm -= 1
            return
        if o == 0x1FF02:
            self.arm = 2
            if self.eot is not None:
                self.after_eot += 1
                return
            sr, pc = L.neo_reg(17), L.neo_reg(29)
            if (sr & 0x700) < 0x300 and self.out_irq is None:      # an AES interrupt (levels 1-3) can come
                self.out_irq = (pc, sr)
            if not 0xC00000 <= pc < 0xD00000 and self.out_ram is None:
                self.out_ram = pc
        elif o == 0x1FF00:
            self.eots += 1
            if self.eot is None:
                self.eot = self.last_poll = t
                self.wd_before_eot = L.neo_watchdog_resets() - self.wd0
        elif o < 0xA0:
            if self.eot is not None:
                if o < 0x94:                           # BRICO_COMMAND_IN: waiting for the next command
                    self.gap = max(self.gap, t - self.last_poll)
                    self.last_poll = t
            elif o >= 0x94 and self.late_param is None and L.neo_host_state() == H_WAIT:
                self.late_param = L.neo_pc()

    def after(self, seconds=CHECK_AFTER):
        """Runs a little after the EOT to see the 68000 wait for the next command."""
        for _ in range(max(1, round(seconds * 60))):
            self.lib.neo_run_frame()

    def end(self, typ, status, secs, values, resets_ok=False):
        """[(level 'FAIL' | 'WARN', message)]; stops watching."""
        L = self.lib
        if not self.ok:
            return []
        L.neo_watch(None)
        if self.eot is not None and self.last_poll is not None:
            self.gap = max(self.gap, L.neo_cycles() - self.last_poll)
        wd = L.neo_watchdog_resets() - self.wd0
        f = []
        if self.out_irq:
            f.append(("FAIL", f"output written with interrupts enabled (SR ${self.out_irq[1]:04x} at "
                              f"${self.out_irq[0]:06x}): an interrupt between the arming read and the value "
                              "corrupts it; write with SR = $2700"))
        if self.out_ram:
            f.append(("FAIL", f"output written from code outside the BIOS ROM (PC ${self.out_ram:06x}): the "
                              "BricoNeo skips the next socket access after the arming read, which is the opcode "
                              "fetch only when the code runs from the ROM"))
        if self.late_param is not None:
            f.append(("WARN", f"P1-P3 read after the 1 ms clear (near PC ${self.late_param:06x}): the block "
                              "reads 0 by then; read the parameters first"))
        if status == "timeout":
            f.append(("FAIL", "no end of transmission (EOT) within the 3 s BricoNeo timeout"))
        elif self.eot is None and status != "error":
            f.append(("FAIL", "watchdog reset before the EOT: call WatchDog in every loop longer than ~100 ms"
                      if wd else "the command ended without an EOT read (console reset?)"))
        if self.eots > 1:
            f.append(("WARN", f"{self.eots} EOT reads: one per command (the extra ones are ignored)"))
        if self.after_eot:
            f.append(("WARN", f"{self.after_eot} word(s) output after the EOT: the BricoNeo ignores them"))
        if L.neo_host_overflow():
            f.append(("FAIL", "more than 2047 output words: the BricoNeo ring buffer wrapped, cap the output"))
        elif typ == TYPE_WORD and self.eot is not None and status == "eot" and len(values) != 1:
            f.append(("WARN", f"word extension sent {len(values)} words: the console shows only the first"))
        if typ == TYPE_VOID and values:
            f.append(("WARN", f"void extension sent {len(values)} word(s): the console shows none"))
        if typ == TYPE_DUMP and self.eot is not None and status == "eot" and len(values) < 2:
            f.append(("WARN", "dump extension without its 2 address words"))
        if secs > CHECK_LONG and status == "eot":
            f.append(("WARN", f"{secs:.2f} s: close to the 3 s BricoNeo timeout (keep tests well below)"))
        if self.eot is not None and self.wd_before_eot:
            f.append(("FAIL", "watchdog reset before the EOT: call WatchDog in every loop longer than ~100 ms"))
        elif self.eot is not None and wd and not resets_ok:
            f.append(("WARN", "watchdog reset after the EOT: the code that keeps running must call WatchDog"))
        if self.eot is not None and not wd and not resets_ok and self.gap > CHECK_POLL_WARN * CPU_HZ:
            big = self.gap >= CHECK_POLL_FAIL * CPU_HZ
            f.append(("FAIL" if big else "WARN",
                      f"after the EOT, BRICO_COMMAND_IN was not read for {self.gap / CPU_HZ * 1000:.2f} ms"
                      + (": a command sent then is missed (the BricoNeo holds it 1 ms)" if big else
                         ": little margin on the 1 ms the BricoNeo holds a command")
                      + "; poll it every ~0.6 ms and jump to DISPATCH_COMMAND"))
        return f


def _run_to_eot(host, line, step=1200):
    """Host.run_blocking with 0.1 ms slices: stops right after the EOT. (status, text, secs, t_sent)"""
    L = host.core.lib
    err = host.start(line)
    for _ in range(2000):              # busy until the 1 ms clear of a command that ended sooner
        if not err or not err.startswith("Busy"):
            break
        L.neo_run(12)
        err = host.start(line)
    t0 = L.neo_cycles()
    if err:
        return "error", err + "\n", 0.0, t0
    while True:
        L.neo_run(step)
        r = host.poll()
        if r:
            return r + (t0,)
        if L.neo_cycles() - t0 > 4 * CPU_HZ:             # the host model times out at 3 s
            return "timeout", "[Timeout]\n", 3.0, t0


def check_command(host, line, resets_ok=False):
    """Runs one command line with ExtCheck, then repeats it as the console loop mode (*Command) does:
    CHECK_RESEND after its EOT and the 1 ms clear. (status, text, secs, findings); findings: see ExtCheck.end.
    Python core only (findings [] on the C core)."""
    L = host.core.lib
    chk = ExtCheck(host.core)
    ext = host.find(line.split()[0]) if line.split() else None
    typ = ext[2] if ext else TYPE_VOID
    chk.begin()
    st, text, secs, _ = _run_to_eot(host, line)
    values = host.last_values if st != "error" else []
    if st != "error":
        chk.after()
    findings = chk.end(typ, st, secs, values, resets_ok)
    if not chk.ok or st != "eot" or resets_ok or chk.eot is None:
        return st, text, secs, findings
    # loop mode: the same command again, CHECK_RESEND after the EOT (and after the 1 ms clear)
    t0 = L.neo_cycles()
    if host.start(line):
        return st, text, secs, findings
    near = t0 + max(0, round(secs * CPU_HZ) - 24000)          # the first run took secs: big slices until 2 ms before
    while L.neo_host_state() in (H_SENT, H_WAIT) and L.neo_cycles() - t0 < 4 * CPU_HZ:
        L.neo_run(1200 if L.neo_cycles() < near else 12)
    r = host.poll() or ("timeout", "", 3.0)
    if r[0] == "eot":
        ready = max(L.neo_cycles(), t0 + CPU_HZ // 1000 + 12) + round(CHECK_RESEND * CPU_HZ)
        L.neo_run(ready - L.neo_cycles())
        if _run_to_eot(host, line)[0] == "timeout":
            findings.append(("FAIL", f"a repeat sent {CHECK_RESEND * 1e6:.0f} us after the EOT (console loop mode "
                                     f"*{line.split()[0]}) is missed: the 68000 is not back waiting for a command"))
        chk.after()                    # settle: a flaw here must not spill over the next command
    return st, text, secs, findings


# ---------------------------------------------------------------------------
# Test cartridge P ROM (same bytes as tools/make_test_cart.py, checked by compare_mame.py)
# ---------------------------------------------------------------------------
# Security code: 61 words (neogeodev wiki "Security code", word 25 = $6606 as in the system ROM)
SECURITY_CODE = [
    0x7600, 0x4A6D, 0x0A14, 0x6600, 0x003C, 0x206D, 0x0A04, 0x3E2D, 0x0A08, 0x13C0,
    0x0030, 0x0001, 0x3210, 0x0C01, 0x00FF, 0x671A, 0x3028, 0x0002, 0xB02D, 0x0ACE,
    0x6610, 0x3028, 0x0004, 0xB02D, 0x0ACF, 0x6606, 0xB22D, 0x0AD0, 0x6708, 0x5088,
    0x51CF, 0xFFD4, 0x3607, 0x4E75, 0x206D, 0x0A04, 0x3E2D, 0x0A08, 0x3210, 0xE049,
    0x0C01, 0x00FF, 0x671A, 0x3010, 0xB02D, 0x0ACE, 0x6612, 0x3028, 0x0002, 0xE048,
    0xB02D, 0x0ACF, 0x6606, 0xB22D, 0x0AD0, 0x6708, 0x5888, 0x51CF, 0xFFD8, 0x3607,
    0x4E75]
TEST_CART_SEC = 0x186


def test_cart_prom():
    """3 MB P ROM in 68000 order: pseudo-random words (fixed seed) + a game header
    ("NEO-GEO", NGH $0999, P ROM size $300000, security code pointer $182 -> $186)."""
    import random
    rnd = random.Random(0xB1C068)
    n = 3 * 0x100000
    # = bytearray(rnd.getrandbits(8) for _ in range(n)), in 0.1 s instead of 1.5 s: each
    # getrandbits(8) is the top byte of one 32-bit Mersenne Twister output, and getrandbits(32 * n)
    # packs n outputs, first one lowest (little-endian), so every 4th byte from byte 3.
    p = bytearray(rnd.getrandbits(32 * n).to_bytes(4 * n, "little")[3::4])
    # vectors like a game's (wiki "68k vector table"): SP $10F300, reset $C00402, the exceptions to
    # the system ROM entry points, VBLANK and timer to the cartridge. With the vector table switch
    # held on the cartridge the console then starts as with a real game (reset = system ROM $402).
    vec = [0x0010F300, 0x00C00402, 0x00C00408, 0x00C0040E, 0x00C00414] + [0x00C00426] * 27
    vec[8], vec[9], vec[15], vec[24], vec[25], vec[26] = 0x00C0041A, 0x00C00420, 0x00C0042C, 0x00C00432, 0x200, 0x204
    for i, v in enumerate(vec):
        p[4 * i:4 * i + 4] = v.to_bytes(4, "big")
    p[0x100:0x108] = b"NEO-GEO\x00"
    p[0x108:0x10A] = (0x0999).to_bytes(2, "big")
    p[0x10A:0x10E] = (0x300000).to_bytes(4, "big")
    p[0x182:0x186] = TEST_CART_SEC.to_bytes(4, "big")
    for i, w in enumerate(SECURITY_CODE):
        p[TEST_CART_SEC + 2 * i:TEST_CART_SEC + 2 * i + 2] = w.to_bytes(2, "big")
    return bytes(p)


# ---------------------------------------------------------------------------
# Cartridges: none, built-in test cartridge, a game ROM set (folder or MAME zip), the
# diagnostic PROG board. Only P1/P2 are on the 68000 bus (the core gets them); S, C, V
# and M1 are loaded and checked (size, CRC32) but not used: the core renders no fix
# layer or sprites and has no YM2610.
# ---------------------------------------------------------------------------
CART_MODES = {"none": 0, "test": 1, "game": 1, "diag": 2}
CHIP_AREAS = {"maincpu": "P", "fixed": "S", "audiocpu": "M1", "ymsnd:adpcma": "V", "ymsnd:adpcmb": "V",
              "ymsnd": "V", "sprites": "C"}
MAX_FILE = 64 << 20          # largest Neo Geo chip is 16 MB; refuse anything silly
MAX_SET = 512 << 20


class CartImage:
    def __init__(self, kind, data=b"", name="", chips=None, notes=None, tiles=None):
        self.kind, self.mode, self.data, self.name = kind, CART_MODES[kind], data, name
        self.tiles = tiles              # RomTiles / SyntheticTiles for the screen, None = no tile
        self.chips = chips or []        # dicts: chip, file, size, crc, expected, status
        self.notes = notes or []

    def describe(self):
        if self.kind == "none":
            return "No cartridge"
        if self.kind == "diag":
            return "Diagnostic PROG board (SRAM 1 MiB)"
        banks = max(0, len(self.data) // 0x100000 - 1)
        return f"{self.name or 'Game cartridge'} (P1 + {banks} P2 bank{'s' if banks != 1 else ''})"

    def report(self):
        lines = [self.describe()]
        for c in self.chips:
            exp = f" list {c['expected']}" if c.get("expected") and c["expected"] != c.get("crc") else ""
            size = f"{c['size']:#x}" if c.get("size") is not None else "-"
            lines.append(f"  {c['chip']:<3} {c['file'] or '-':<22} {size:>9}  CRC32 {c.get('crc') or '-':<8}{exp}  {c['status']}")
        lines += [f"  {n}" for n in self.notes]
        return "\n".join(lines)


def make_cart(kind):
    if kind == "none":
        return CartImage("none")
    if kind == "test":
        return CartImage("test", test_cart_prom(), "Built-in test cartridge (NGH 0999)",
                         notes=["Generated P ROM: header + security code at $186, pseudo-random words "
                                "(same bytes as the MAME bench cartridge 'brtest').",
                                "Tiles for the screen: generated here (S: a 5 x 7 font at the ASCII codes, "
                                "C: numbered tiles with an F), not the MAME bench cartridge's."],
                         tiles=SyntheticTiles())
    if kind == "diag":
        import random
        rnd = random.Random(0x5EA)       # SRAM power-on content: anything
        return CartImage("diag", rnd.getrandbits(32 * 0x100000).to_bytes(4 * 0x100000, "little")[3::4],
                         "Diagnostic PROG board", notes=[
                             "jwestfall69 neogeo-diag-aes-prog: one 1 MiB 16-bit SRAM read in P1 and P2, "
                             "written through P2 (byte lanes by /PORTWEU, /PORTWEL)."])
    raise ValueError(f"unknown cartridge '{kind}': none, test, diag or a ROM set path")


def _crc(data):
    import zlib
    return f"{zlib.crc32(data) & 0xFFFFFFFF:08x}"


def _word_swap(data):
    b = bytearray(data)
    b[0::2], b[1::2] = data[1::2], data[0::2]
    return bytes(b)


def read_rom_set(path):
    """{file name (lower case): bytes} from a folder (top level) or a .zip (MAME romset)."""
    from pathlib import Path
    import zipfile
    p, files, total = Path(path), {}, 0
    if p.is_dir():
        items = [(f.name, f.stat().st_size, f.read_bytes) for f in sorted(p.iterdir()) if f.is_file()]
    elif zipfile.is_zipfile(p):
        z = zipfile.ZipFile(p)
        items = [(Path(i.filename).name, i.file_size, (lambda i=i: z.read(i)))
                 for i in z.infolist() if not i.is_dir()]
    else:
        raise ValueError(f"{p.name}: not a folder nor a zip file")
    for name, size, read in items:
        if not name or name.startswith(".") or name.lower().endswith((".xml", ".txt", ".md", ".dat")):
            continue
        if size > MAX_FILE or total + size > MAX_SET:
            raise ValueError(f"{name}: too large for a Neo Geo ROM set")
        total += size
        files[name.lower()] = read()
    if not files:
        raise ValueError(f"{p.name}: no ROM file")
    return files


def parse_softlist(xml_path):
    """MAME software list (hash/neogeo.xml) -> {name: {"description", "areas": {area: (size,
    [ (name|None, offset, size, crc|None, loadflag|None) ])}}}. The file is the user's: parsed
    with expat, entities not expanded beyond the standard ones."""
    import xml.etree.ElementTree as ET
    out = {}
    for sw in ET.parse(str(xml_path)).getroot().iter("software"):
        areas = {}
        for part in sw.iter("part"):
            for da in part.iter("dataarea"):
                roms = []
                for r in da.iter("rom"):
                    roms.append((r.get("name"), int(r.get("offset", "0"), 0), int(r.get("size", "0"), 0),
                                 (r.get("crc") or "").lower() or None, r.get("loadflag")))
                areas[da.get("name")] = (int(da.get("size", "0"), 0), roms)
        out[sw.get("name")] = {"description": (sw.findtext("description") or "").strip(), "areas": areas,
                               "cloneof": sw.get("cloneof")}
    return out


def _build_area(size, roms, files, by_crc):
    """MAME ROM loading for one data area: load16_word_swap, load16_byte, continue, ignore."""
    region = bytearray(size)                 # MAME regions start zero-filled
    cur, pos, flag = None, 0, None
    for name, off, sz, crc, lf in roms:
        if name:
            cur = by_crc.get(crc) if crc else None
            if cur is None:
                cur = files.get(name.lower())
            if cur is None:
                return None
            pos, flag = 0, lf
        elif lf == "ignore":
            pos += sz
            continue
        elif lf != "continue" or cur is None:
            continue                         # fill/unknown: left zero
        chunk = cur[pos:pos + sz]
        pos += sz
        mode = flag if lf == "continue" else lf
        if mode == "load16_word_swap":
            chunk = _word_swap(chunk)
        if mode == "load16_byte":
            end = min(off + 2 * len(chunk), size)
            region[off:end:2] = chunk[:(end - off + 1) // 2]
        else:
            region[off:off + len(chunk)] = chunk[:max(0, size - off)]
    return bytes(region)


def _p_window(maincpu):
    """MAME maincpu region -> P1 MB + whole 1 MB P2 banks (a smaller chip is mirrored, as it
    ignores the upper address lines)."""
    if not maincpu:
        raise ValueError("no P ROM")
    p1 = maincpu[:0x100000]
    while len(p1) < 0x100000:
        p1 = (p1 + p1)[:0x100000]
    p2 = maincpu[0x100000:]
    if len(p2) % 0x100000:
        last = p2[len(p2) // 0x100000 * 0x100000:]
        while len(last) < 0x100000:
            last = (last + last)[:0x100000]
        p2 = p2[:len(p2) // 0x100000 * 0x100000] + last
    data = p1 + p2
    if len(data) > 0x1000000:
        raise ValueError("P ROM larger than 16 MB")
    return data


def _chip_of(name):
    m = re.search(r"(?:^|[-_.])(?:e|s)?(p|s|m|v|c)(\d)(?:[._-]|$)", name.lower())
    return {"p": "P", "s": "S", "m": "M1", "v": "V", "c": "C"}[m.group(1)] if m else "?"


def load_cartridge(path, softlist=None):
    """A game ROM set (folder or MAME zip) -> CartImage. With the official MAME list
    (hash/neogeo.xml) the set is identified by its CRCs, loaded with the list's layout and
    every chip checked; without it, P1/P2 are found by name and the byte order by the
    NEO-GEO header (CRCs listed, not checked)."""
    from pathlib import Path
    files = read_rom_set(path)
    crcs = {n: _crc(d) for n, d in files.items()}
    by_crc = {crcs[n]: d for n, d in files.items()}
    notes, chips = [], []
    if softlist:
        lst = parse_softlist(softlist) if not isinstance(softlist, dict) else softlist
        best, score = None, 0
        for sname, sw in lst.items():
            want = {c for _, (_, roms) in sw["areas"].items() for (_, _, _, c, _) in roms if c}
            s = len(want & set(by_crc))
            if s > score or (s == score and s and sname == Path(path).stem.lower()):
                best, score = sname, s
        if best is None:
            notes.append(f"No software of {Path(str(softlist)).name if not isinstance(softlist, dict) else 'the list'} "
                         "matches these files' CRC32: unknown or bad dump. Layout guessed from the header.")
        else:
            sw = lst[best]
            seen = set()
            for area, (size, roms) in sw["areas"].items():
                for name, off, sz, crc, lf in roms:
                    if not name:
                        continue
                    got = by_crc.get(crc) if crc else None
                    fname = next((n for n in files if crcs[n] == crc), None) if got is not None else None
                    if got is None and name.lower() in files:
                        fname = name.lower()
                    if fname:
                        seen.add(fname)
                    st = ("OK" if fname and crcs[fname] == crc else
                          "MISSING" if not fname else "BAD CRC (dump differs from the official list)")
                    if not crc:
                        st = "no CRC in the list (no good dump known)" if fname else "MISSING"
                    chips.append({"chip": CHIP_AREAS.get(area, area), "file": fname or name,
                                  "size": len(files[fname]) if fname else None,
                                  "crc": crcs.get(fname), "expected": crc, "status": st})
            for n in files:
                if n not in seen:
                    chips.append({"chip": _chip_of(n), "file": n, "size": len(files[n]), "crc": crcs[n],
                                  "expected": None, "status": "not in the list for this game"})
            if "maincpu" not in sw["areas"]:
                raise ValueError(f"{best}: the list has no maincpu (P ROM) area")
            size, roms = sw["areas"]["maincpu"]
            maincpu = _build_area(size, roms, files, by_crc)
            if maincpu is None:
                raise ValueError(f"{best}: P ROM file missing, cannot insert the cartridge")
            bad = [c for c in chips if c["status"] != "OK"]
            notes.append(f"Identified as '{best}' ({sw['description']}) by {score} CRC32 from the official list"
                         + (f"; {len(bad)} chip(s) not OK" if bad else "; every chip OK"))
            if any(c["status"] == "MISSING" for c in chips):
                notes.append("MISSING: not in this set. A MAME split clone set keeps the chips it shares in "
                             "its parent's zip: merge them, or check the parent too.")
            tiles = RomTiles(_build_area(*sw["areas"]["fixed"], files, by_crc) if "fixed" in sw["areas"] else None,
                             _build_area(*sw["areas"]["sprites"], files, by_crc) if "sprites" in sw["areas"] else None)
            notes.append(tiles.note())
            return CartImage("game", _p_window(maincpu), f"{best} - {sw['description']}", chips, notes, tiles)
    # no list (or no match): P1 / P2 by name, byte order and layout by the header
    ps = sorted((n for n in files if _chip_of(n) == "P"),
                key=lambda n: int(re.search(r"p(\d)", n).group(1)) if re.search(r"p(\d)", n) else 9)
    if not ps:
        raise ValueError("no P ROM file (name with p1 / p2) in the set")
    p1 = files[ps[0]]
    swap = None
    for sw_ in (True, False):
        d = _word_swap(p1) if sw_ else p1
        if d[0x100:0x107] == b"NEO-GEO":
            swap, layout = sw_, "flat"
        elif len(d) > 0x100107 and d[0x100100:0x100107] == b"NEO-GEO":
            swap, layout = sw_, "halves"
        if swap is not None:
            break
    if swap is None:
        raise ValueError(f"{ps[0]}: no NEO-GEO header in either byte order (encrypted or not a P1)")
    conv = (lambda d: _word_swap(d)) if swap else (lambda d: d)
    p = conv(p1)
    if layout == "halves":              # MAME ROM_CONTINUE: second MB at $000000, first at $100000
        p = p[0x100000:0x200000] + p[:0x100000] + p[0x200000:]
    maincpu = p                         # P1 (then P2 bank 0.. when the P1 file is over 1 MB)
    for n in ps[1:]:
        if len(maincpu) < 0x100000:
            maincpu = (maincpu * (0x100000 // len(maincpu) + 1))[:0x100000]
        maincpu += conv(files[n])
    for n in files:
        chips.append({"chip": _chip_of(n), "file": n, "size": len(files[n]), "crc": crcs[n],
                      "expected": None, "status": "not checked (no official list)"})
    notes.append(f"P ROM {'byte-swapped files (MAME order)' if swap else 'files in 68000 order'}, "
                 f"layout from the NEO-GEO header{' (P1 halves swapped, ROM_CONTINUE)' if layout == 'halves' else ''}. "
                 "Give the MAME list hash/neogeo.xml to check every chip's CRC32.")
    # tiles by name: S1, and the C pairs interleaved byte by byte (odd chip first), as MAME loads them
    num = lambda n: int(re.search(r"[sc](\d)", n).group(1)) if re.search(r"[sc](\d)", n) else 9
    ss = sorted((n for n in files if _chip_of(n) == "S"), key=num)
    cs = sorted((n for n in files if _chip_of(n) == "C"), key=num)
    spr = bytearray()
    for i in range(0, len(cs) - 1, 2):
        a, b = files[cs[i]], files[cs[i + 1]]
        m = min(len(a), len(b))
        pair = bytearray(2 * m)
        pair[0::2], pair[1::2] = a[:m], b[:m]
        spr += pair
    tiles = RomTiles(files[ss[0]] if ss else None, bytes(spr) if spr else None)
    notes.append(tiles.note())
    return CartImage("game", _p_window(maincpu), Path(path).stem, chips, notes, tiles)


# Simulated faults
# ---------------------------------------------------------------------------
FAULT_REGIONS = {"wram": 0, "pal": 1, "vramlo": 2, "vramhi": 3, "line": 4, "bios": 5, "cart": 6, "vec": 7, "lspc": 8}
REGION_NAMES = {0: "WRAM", 1: "Palette RAM", 2: "VRAM lower (slow)", 3: "VRAM upper (fast)",
                4: "LSPC line counter", 5: "BIOS socket (68000 -> BricoNeo)", 6: "Cartridge slot P bus",
                7: "Vector table switch", 8: "LSPC registers (decoding)"}
FAULT_KINDS = {"data": 0, "addr": 1, "lane": 2, "float": 3, "strobe": 2, "stuck": 0, "sel": 4, "leak": 5}
# 0-3 strobes; 4-5 /PORTOE (P2 output enable); 6-9 the OE dead behind a 245 / NEO-G0 / NEO-BUF (bus hold)
STROBES = ["portwel", "portweu", "romoel", "romoeu", "portoel", "portoeu",
           "romoel245", "romoeu245", "portoel245", "portoeu245"]
# the BIOS socket has no data faults: a bad D line stops the boot, nothing to test
DATA_BITS = {0: 15, 1: 15, 2: 15, 3: 15, 4: 8, 5: -1, 6: 15, 7: 0, 8: -1}
ADDR_RANGE = {0: (1, 15), 1: (1, 13), 2: (0, 14), 3: (0, 10), 5: (1, 16), 6: (1, 19)}
# decoding faults (TestDecode): the decoder of the region uses an address line it should ignore, so the
# chip answers only when that line is at the given level (the mirrors of WRAM, palette RAM, LSPC registers)
SEL_RANGE = {0: (16, 19), 1: (13, 21), 8: (4, 16)}

FAULT_HELP = ("Fault syntax: REGION:data:BIT:0|1 (data bit stuck), REGION:addr:LINE:0|1 (address line stuck),\n"
              "wram:lane:lower|upper (WRAM chip dead), bios:float:LINE (BIOS socket line unstable).\n"
              "REGION = wram, pal, vramlo, vramhi, line, bios, cart. Bits: data 0-15 (line counter 0-8);\n"
              "address WRAM A1-A15, pal A1-A12 + 13 = bank select, vramlo 0-14, vramhi 0-10,\n"
              "bios A1-A16 (socket, 68000 -> BricoNeo; address faults only), cart A1-A19 (slot).\n"
              "Cartridge slot: cart:data:BIT:0|1, cart:addr:LINE:0|1, cart:float:BIT (D line unstable),\n"
              "cart:strobe:portwel|portweu|romoel|romoeu|portoel|portoeu (strobe dead; the OE ones: the 68000 reads\n"
              "its prefetched word), ...245 suffix (romoel245 ...): OE dead behind a 245, bus hold. Needs --cart test or diag.\n"
              "Vector table switch (system latch Q1) held: vec:stuck:bios (system ROM) or vec:stuck:cart.\n"
              "Address decoding (TestDecode): wram:sel:LINE:0|1 (A16-A19), pal:sel:LINE:0|1 (A13-A21), lspc:sel:LINE:0|1 (A4-A16):\n"
              "the chip answers only when that line is at that level (a line the decoder should ignore); wram:leak: WRAM writes\n"
              "also reach the palette RAM.\n"
              "Example: --fault wram:data:5:1 --fault pal:addr:13:0 --fault bios:addr:15:1")


def parse_fault(spec):
    """'wram:data:5:1' -> (region, kind, bit, value). Raises ValueError with a readable reason."""
    parts = spec.strip().lower().split(":")
    if parts == ["wram", "leak"]:
        return 0, 5, 0, 1
    if len(parts) < 3 or parts[0] not in FAULT_REGIONS or parts[1] not in FAULT_KINDS:
        raise ValueError(f"bad fault '{spec}'. " + FAULT_HELP.splitlines()[0])
    region, kind = FAULT_REGIONS[parts[0]], FAULT_KINDS[parts[1]]
    if region == 7 or parts[1] == "stuck":
        if region != 7 or parts[1] != "stuck" or len(parts) != 3 or parts[2] not in ("bios", "cart"):
            raise ValueError("vector table switch: vec:stuck:bios or vec:stuck:cart")
        return region, 0, 0, 1 if parts[2] == "cart" else 0
    if kind == 4 or region == 8:
        if kind != 4 or region not in SEL_RANGE or len(parts) != 4 or parts[3] not in ("0", "1") or not parts[2].isdigit():
            raise ValueError("decoding fault: " + ", ".join(f"{k}:sel:LINE:0|1 (A{a}-A{b})" for k, (a, b) in
                             ((n, SEL_RANGE[r]) for n, r in (("wram", 0), ("pal", 1), ("lspc", 8)))) + "; or wram:leak")
        lo, hi = SEL_RANGE[region]
        if not lo <= int(parts[2]) <= hi:
            raise ValueError(f"{REGION_NAMES[region]}: address lines {lo}-{hi}")
        return region, 4, int(parts[2]), int(parts[3])
    if kind == 5:
        raise ValueError("only wram:leak")
    if kind == 2 and region == 6:
        if parts[1] != "strobe" or len(parts) != 3 or parts[2] not in STROBES:
            raise ValueError("cartridge strobe: cart:strobe:" + "|".join(STROBES))
        return region, kind, 0, STROBES.index(parts[2])
    if kind == 3 and region == 6:
        if len(parts) != 3 or not parts[2].isdigit() or not 0 <= int(parts[2]) <= 15:
            raise ValueError("unstable data line: cart:float:BIT, BIT 0-15")
        return region, kind, int(parts[2]), 0
    if kind == 2:
        if region != 0 or parts[1] != "lane" or parts[2] not in ("lower", "upper"):
            raise ValueError("byte lane faults: wram:lane:lower or wram:lane:upper")
        return region, kind, 0, 1 if parts[2] == "upper" else 0
    if kind == 3:
        if region != 5 or len(parts) != 3 or not parts[2].isdigit() or not 1 <= int(parts[2]) <= 16:
            raise ValueError("unstable line: bios:float:LINE, LINE 1-16")
        return region, kind, int(parts[2]), 0
    if len(parts) != 4 or parts[3] not in ("0", "1") or not parts[2].isdigit():
        raise ValueError(f"bad fault '{spec}': expected REGION:{parts[1]}:BIT:0|1")
    bit, value = int(parts[2]), int(parts[3])
    if kind == 0 and bit > DATA_BITS[region]:
        if DATA_BITS[region] < 0:
            raise ValueError(f"{REGION_NAMES[region]}: address faults only (a bad data line stops the boot)")
        raise ValueError(f"{REGION_NAMES[region]}: data bits 0-{DATA_BITS[region]}")
    if kind == 1:
        if region not in ADDR_RANGE:
            raise ValueError("the line counter has no address lines")
        lo, hi = ADDR_RANGE[region]
        if not lo <= bit <= hi:
            raise ValueError(f"{REGION_NAMES[region]}: address lines {lo}-{hi}")
    return region, kind, bit, value


def describe_fault(f):
    region, kind, bit, value = f
    name = REGION_NAMES[region]
    if region == 7:
        return f"{name}: held on the {'cartridge' if value else 'system ROM'} (latch Q1)"
    if kind == 4:
        return f"{name}: the decoder uses A{bit}, it answers only when A{bit} = {value}"
    if kind == 5:
        return f"{name}: its write strobe also reaches the palette RAM"
    if kind == 2 and region == 6:
        return f"{name}: /{STROBES[value].upper()} dead"
    if kind == 3 and region == 6:
        return f"{name}: data line D{bit} unstable"
    if kind == 2:
        return f"{name}: {'upper (D8-D15)' if value else 'lower (D0-D7)'} chip dead"
    if kind == 0:
        return f"{name}: data bit D{bit} stuck at {value}"
    if kind == 3:
        return f"{name}: address line A{bit} unstable"
    if region == 1 and bit == 13:
        return f"{name}: bank select stuck at bank {value}"
    return f"{name}: address line A{bit} stuck at {value}"


def fault_spec(f):
    region, kind, bit, value = f
    r = {v: k for k, v in FAULT_REGIONS.items()}[region]
    if region == 7:
        return f"vec:stuck:{'cart' if value else 'bios'}"
    if kind == 5:
        return f"{r}:leak"
    if kind == 4:
        return f"{r}:sel:{bit}:{value}"
    if kind == 2 and region == 6:
        return f"{r}:strobe:{STROBES[value]}"
    if kind == 2:
        return f"{r}:lane:{'upper' if value else 'lower'}"
    if kind == 3:
        return f"{r}:float:{bit}"
    return f"{r}:{'data' if kind == 0 else 'addr'}:{bit}:{value}"


def apply_faults(core, faults):
    core.lib.neo_fault_clear()
    for f in faults:
        if core.lib.neo_fault_add(*f) != 0:
            raise ValueError(f"fault refused by the core: {describe_fault(f)}")


# ---------------------------------------------------------------------------
# Tile layers: the screen from VRAM. The core keeps VRAM and the palette but draws nothing;
# this draws the fix layer and the sprites from them, for the test screens of the ROM (TestGfx).
# Layer rules as MAME snk/neogeo_spr.cpp. NOT a game-accurate renderer:
# - vertical shrink is approximated (source line = window line * 256 / (shrink + 1)): the real
#   table is the L0 ROM, which is SNK's and not included;
# - no auto-animation, no 96 sprites per line limit, windows over 32 tiles not handled;
# - tiles: the cartridge's S and C ROMs when the set has them (not decrypted: CMC / PCM sets show
#   noise), generated tiles for the built-in test cartridge, none without a cartridge or with the
#   PROG board (no CHA board: nothing drives the tile data).
# ---------------------------------------------------------------------------
_FONT = {" ": "0000000", "-": "000V000", "0": "EHJLPHE", "1": "4C4444E", "2": "EH1248V", "3": "U11E11U", "4": "26AIV22",
         "5": "VGU11HE", "6": "68GUHHE", "7": "V124888", "8": "EHHEHHE", "9": "EHHF12C", "A": "EHHVHHH", "B": "UHHUHHU",
         "C": "EHGGGHE", "D": "UHHHHHU", "E": "VGGUGGV", "F": "VGGUGGG", "G": "EHGNHHF", "H": "HHHVHHH", "I": "E44444E",
         "J": "72222IC", "K": "HIKOKIH", "L": "GGGGGGV", "M": "HRLLHHH", "N": "HPLJHHH", "O": "EHHHHHE", "P": "UHHUGGG",
         "Q": "EHHHLID", "R": "UHHUKIH", "S": "FGGE11U", "T": "V444444", "U": "HHHHHHE", "V": "HHHHHA4", "W": "HHHLLRH",
         "X": "HHA4AHH", "Y": "HHA4444", "Z": "V1248GV"}       # 5 x 7, one base-32 digit per row
_ZOOM_X = ["0000000010000000", "0000100010000000", "0000100010001000", "0010100010001000", "0010100010001010",
           "0010101010001010", "0010101010101010", "1010101010101010", "1010101011101010", "1011101011101010",
           "1011101011101011", "1011101111101011", "1011101111101111", "1111101111101111", "1111101111111111",
           "1111111111111111"]                                   # MAME zoom_x_tables: the columns kept


class SyntheticTiles:
    """Tiles of the built-in test cartridge. Fix: a 5 x 7 font at the ASCII codes of the digits,
    capitals, space and '-', a hollow box for every other tile except $00, $20 and $FF (blank:
    VRAM is zero at power-on in the core, a real one holds anything).
    Sprites: a frame in colour 1 + n % 15, an F (shows the flips) and the low 8 bits of the
    tile number along the bottom, both in colour 13."""
    synthetic = True

    def __init__(self, fix_tiles=0x1000, sprite_tiles=0x2000):
        self._f, self._s = {}, {}
        self.nf, self.ns = fix_tiles, sprite_tiles      # chip sizes: tile numbers wrap, as on a ROM

    def note(self):
        return "Tiles: generated"

    def fix(self, n):
        n %= self.nf
        if n not in self._f:
            t = None
            ch = chr(n & 0xFF) if n < 0x100 else ""
            if ch in _FONT and ch != " ":
                t = [[0] * 8] + [[0] + [1 if int(row, 32) >> (4 - x) & 1 else 0 for x in range(5)] + [0, 0]
                                 for row in _FONT[ch]]
            elif n not in (0x00, 0x20, 0xFF):
                t = [[1 if (x in (1, 6) and 1 <= y <= 6) or (y in (1, 6) and 1 <= x <= 6) else 0 for x in range(8)]
                     for y in range(8)]
            self._f[n] = t
        return self._f[n]

    def sprite(self, n):
        n %= self.ns
        if n not in self._s:
            t = [[0] * 16 for _ in range(16)]
            c = 1 + n % 15
            for i in range(16):
                t[0][i] = t[15][i] = t[i][0] = t[i][15] = c
            for y in range(3, 13):
                t[y][4] = 13
            for x in range(4, 11):
                t[3][x] = 13
            for x in range(4, 9):
                t[7][x] = 13
            for b in range(8):
                if n >> b & 1:
                    t[13][13 - b] = 13
            self._s[n] = t
        return self._s[n]


class RomTiles:
    """Tiles of a game ROM set: S ROM (32 bytes a tile) and the C ROMs as MAME loads them
    (C1/C2 interleaved byte by byte, 128 bytes a tile). A blank tile is None."""
    synthetic = False

    def __init__(self, s_rom, c_rom):
        self.s, self.c = s_rom or b"", c_rom or b""
        self._f, self._s = {}, {}

    def note(self):
        return (f"Tiles for the screen: S ROM {len(self.s) // 32} tiles, C ROMs {len(self.c) // 128} tiles"
                + ("" if self.s and self.c else " (a missing chip gives no tile)")
                + ". Not decrypted: an encrypted set shows noise.")

    def fix(self, n):
        if n not in self._f:
            t = None
            if self.s:
                o = (n * 32) % (len(self.s) - len(self.s) % 32 or 32)
                g = self.s[o:o + 32]
                if len(g) == 32 and any(g):
                    t = [[(g[(0x10, 0x18, 0x00, 0x08)[x >> 1] + y] >> (4 if x & 1 else 0)) & 15 for x in range(8)]
                         for y in range(8)]
            self._f[n] = t
        return self._f[n]

    def sprite(self, n):
        if n not in self._s:
            t = None
            if len(self.c) >= 128:
                o = (n * 128) % (len(self.c) - len(self.c) % 128)
                g = self.c[o:o + 128]
                if any(g):
                    t = []
                    for y in range(16):
                        row = []
                        for half in (0x40, 0x00):       # left 8 pixels, then right 8
                            b0, b1, b2, b3 = (g[half | i | y << 2] for i in (0, 2, 1, 3))
                            row += [(b3 >> x & 1) << 3 | (b2 >> x & 1) << 2 | (b1 >> x & 1) << 1 | (b0 >> x & 1)
                                    for x in range(8)]
                        t.append(row)
            self._s[n] = t
        return self._s[n]


def test_cart_tile_roms(fix_tiles=0x1000, sprite_tiles=0x2000):
    """The built-in test cartridge's tiles as ROM files: (S1, C1, C2), in the chips' own formats
    (what RomTiles decodes). tools/make_test_cart.py writes them, so the MAME bench cartridge
    shows the same tiles as this emulator."""
    src = SyntheticTiles()
    s1 = bytearray(fix_tiles * 32)
    for n in range(fix_tiles):
        t = src.fix(n)
        if t:
            for y in range(8):
                for x in range(8):
                    s1[n * 32 + (0x10, 0x18, 0x00, 0x08)[x >> 1] + y] |= t[y][x] << (4 if x & 1 else 0)
    c = bytearray(sprite_tiles * 128)                 # C1 / C2 interleaved byte by byte, as MAME loads them
    for n in range(sprite_tiles):
        t = src.sprite(n)
        for y in range(16):
            for half, x0 in ((0x40, 0), (0x00, 8)):
                for x in range(8):
                    v = t[y][x0 + x]
                    for plane, i in enumerate((0, 2, 1, 3)):
                        if v >> plane & 1:
                            c[n * 128 + (half | i | y << 2)] |= 1 << x
    return bytes(s1), bytes(c[0::2]), bytes(c[1::2])


def render_layers(vram, pal, tiles):
    """Fix layer and sprites from VRAM ($0000-$87FF) and the 4096 colours of the palette bank.
    Returns 224 rows of 320 entries: a colour word, or None where the backdrop shows.
    tiles = None (no cartridge): every row is None."""
    W, H = 320, 224
    out = [[None] * W for _ in range(H)]
    if tiles is None:
        return out
    x = y = rows = zy = 0
    for s in range(381):                                # low numbers first: higher ones on top
        y3, z2 = vram[0x8200 + s], vram[0x8000 + s]
        zx = z2 >> 8 & 15
        if y3 & 0x40:                                   # sticky: glued to the right of the previous one
            x = (x + (vram[0x8000 + s - 1] >> 8 & 15) + 1) & 0x1FF if s else 0
        else:
            x = vram[0x8400 + s] >> 7
            y = (0x200 - (y3 >> 7)) & 0x1FF
            rows, zy = y3 & 0x3F, z2 & 0xFF
        if not rows:
            continue
        x0 = x - 0x200 if x >= 0x1F0 else x
        if x0 >= W:
            continue
        keep = _ZOOM_X[zx]
        base = s * 64
        for wl in range(min(rows, 32) * 16):
            sy = ((y + wl) & 0x1FF) - 16
            if not 0 <= sy < H:
                continue
            src = wl if zy == 0xFF else wl * 256 // (zy + 1)
            if src >= (512 if zy == 0xFF else 256):
                continue
            ti, line = (src >> 4) & 31, src & 15
            lo, at = vram[base + ti * 2], vram[base + ti * 2 + 1]
            t = tiles.sprite(lo | (at >> 4 & 15) << 16)
            if t is None:
                continue
            row = t[line ^ 15 if at & 2 else line]
            po = (at >> 8) * 16
            dst = out[sy]
            xo = x0
            for sx in range(16):
                if keep[sx] == "1":
                    c = row[15 - sx if at & 1 else sx]
                    if c and 0 <= xo < W:
                        dst[xo] = pal[po + c]
                    xo += 1
    for col in range(40):                               # fix layer: above everything
        for r in range(2, 30):
            w = vram[0x7000 + col * 32 + r]
            t = tiles.fix(w & 0xFFF)
            if t is None:
                continue
            po = (w >> 12) * 16
            for ty in range(8):
                dst, row = out[(r - 2) * 8 + ty], t[ty]
                for tx in range(8):
                    if row[tx]:
                        dst[col * 8 + tx] = pal[po + row[tx]]
    return out


def write_png(path, rows, scale=1):
    """rows: lists of (r, g, b). A plain 8-bit RGB PNG (no dependency)."""
    import zlib
    h, w = len(rows) * scale, len(rows[0]) * scale
    raw = bytearray()
    for row in rows:
        line = b"\x00" + b"".join(bytes(p) * scale for p in row)
        raw += line * scale
    def chunk(tag, data):
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
    with open(path, "wb") as f:
        f.write(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0))
                + chunk(b"IDAT", zlib.compress(bytes(raw), 9)) + chunk(b"IEND", b""))


# ---------------------------------------------------------------------------
# Real console logs (PuTTY / Tera Term session log of the BricoNeo console)
# ---------------------------------------------------------------------------
_ESC = re.compile(r"\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b[@-Z\\-_]")
# Brico16Bits built-in commands (Commands/*.cpp, COMMAND_NAME), lower case
CONSOLE_BUILTINS = {"loadbank", "storebank", "bootsel", "clearbuffer", "dbg", "delay", "free", "freq", "listroms",
                    "ls", "readword", "readwords", "reset", "sendrompart", "setromw", "trace", "?"}


def clean_terminal(raw):
    """Terminal output -> plain lines, as the screen showed them: colour codes removed, CR, backspace
    and erase-line applied (the console redraws its prompt with CR + ESC[2K and erases with BS SP BS)."""
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8", errors="replace")
    lines, line, col = [], [], 0
    pos = 0
    for m in list(_ESC.finditer(raw)) + [None]:
        chunk = raw[pos:m.start()] if m else raw[pos:]
        for ch in chunk:
            if ch == "\n":
                lines.append("".join(line).rstrip()); line, col = [], 0
            elif ch == "\r":
                col = 0
            elif ch == "\b":
                col = max(0, col - 1)
            elif ch < " " and ch != "\t":
                continue                                  # bell and other controls
            else:
                if col < len(line):
                    line[col] = ch
                else:
                    line.append(ch)
                col += 1
        if m is None:
            break
        seq = m.group()
        if seq in ("\x1b[2K", "\x1b[K", "\x1b[0K"):
            if seq == "\x1b[2K":
                line, col = [], 0
            else:
                del line[col:]
        elif seq in ("\x1b[2J", "\x1b[H"):
            if seq == "\x1b[2J":
                lines.append(""); line, col = [], 0
        pos = m.end()
    if line:
        lines.append("".join(line).rstrip())
    return lines


def parse_console_log(raw, ext_names):
    """Session log -> [{'line': typed command, 'name': extension or built-in, 'output': text}].
    A command line is '> ' followed by an extension name, a console built-in or ';'. Other lines
    (extension output, even when it starts with '> ') belong to the command above them."""
    exts = {n.lower(): n for n in ext_names}
    entries, cur = [], None
    for line in clean_terminal(raw):
        if line.startswith(">"):
            rest = line[1:].strip()
            word = rest.split()[0].lstrip("*@") if rest else ""
            if not rest:
                cur = None                                 # idle prompt
                continue
            if rest.startswith(";") or word.lower() in exts or word.lower() in CONSOLE_BUILTINS:
                name = ";" if rest.startswith(";") else exts.get(word.lower(), word)
                cur = {"line": rest, "name": name, "output": []}
                entries.append(cur)
                continue
        if cur is not None:
            cur["output"].append(line)
    for e in entries:
        while e["output"] and not e["output"][-1].strip():
            e["output"].pop()
        e["output"] = "\n".join(e["output"]) + ("\n" if e["output"] else "")
    return entries


# ---------------------------------------------------------------------------
# Sound: the YM2610 SSG part (AY-3-8910 compatible) from the registers the Z80 wrote.
# Square-wave tones only (no noise, no envelope, no FM / ADPCM): enough to hear that the Z80
# received the command and programmed the sound chip.
SSG_CLOCK = 2000000                  # YM2610 8 MHz / 4; tone f = SSG_CLOCK / (16 x period)


def ssg_voices(regs):
    """Audible SSG channels: [(channel 'A'/'B'/'C', frequency Hz, volume 0-15)]."""
    out = []
    for ch in range(3):
        period = regs[2 * ch] | ((regs[2 * ch + 1] & 0x0F) << 8)
        vol = regs[8 + ch] & 0x1F
        vol = 15 if vol & 0x10 else vol          # envelope mode: taken as full volume
        if not (regs[7] >> ch) & 1 and vol and period:
            out.append(("ABC"[ch], SSG_CLOCK / (16 * period), vol))
    return out


def ssg_describe(voices):
    return ", ".join(f"tone {c} {f:.0f} Hz vol {v}" for c, f, v in voices) if voices else "silent"


def ssg_wav(voices, seconds=4.0, rate=22050):
    """A mono 16-bit WAV of the voices (square waves, AY logarithmic volume), as bytes."""
    import io, wave
    n = int(seconds * rate)
    amp = [0] + [int(9000 * 10 ** ((v - 15) * 1.5 / 20)) for v in range(1, 16)]
    buf = bytearray(2 * n)
    if voices:
        parts = []
        for _c, f, v in voices:
            half = rate / (2 * f)
            a = amp[v] // len(voices) if len(voices) > 1 else amp[v]
            parts.append((half, a))
        for i in range(n):
            x = 0
            for half, a in parts:
                x += a if int(i / half) & 1 else -a
            struct.pack_into("<h", buf, 2 * i, max(-32767, min(32767, x)))
    out = io.BytesIO()
    with wave.open(out, "wb") as w:
        w.setnchannels(1); w.setsampwidth(2); w.setframerate(rate); w.writeframes(bytes(buf))
    return out.getvalue()

# ---------------------------------------------------------------------------
# Embedded core
# ---------------------------------------------------------------------------
C_CORE_NAMES = ("neocore.dll",) if IS_WIN else ("libneocore.so", "libneocore.dylib")


def core_path():
    """The emulator core: None = the built-in Python core (the default, nothing to install);
    else the path of a C core library (neocore.c, built by emulator/build_core.py) that is
    faster: put neocore.dll (Windows) or libneocore.so (Linux) next to this script, or give
    its path in the BRICO68K_CORE environment variable (BRICO68K_CORE=python forces the
    Python core). Both give the same results word for word."""
    env = os.environ.get("BRICO68K_CORE", "").strip()
    if env.lower() == "python":
        return None
    if env:
        if not Path(env).is_file():
            raise RuntimeError(f"BRICO68K_CORE: no file {env}")
        return Path(env)
    for name in C_CORE_NAMES:
        if (TOOL_DIR / name).is_file():
            return TOOL_DIR / name
    return None


class SoundOut:
    """Plays the SSG voices as a looping WAV, standard library only: winsound on Windows, else
    the first of paplay / pw-play / aplay / afplay found. Without any, it stays silent."""

    def __init__(self):
        import shutil, tempfile
        self.key = None
        self.proc = None
        self.dir = Path(tempfile.gettempdir())
        self.win = None
        self.player = None
        if IS_WIN:
            try:
                import winsound
                self.win = winsound
            except ImportError:
                pass
        else:
            for p in ("paplay", "pw-play", "aplay", "afplay"):
                if shutil.which(p):
                    self.player = p
                    break
        self.available = bool(self.win or self.player)

    def stop(self):
        if self.win:
            self.win.PlaySound(None, 0)
        if self.proc and self.proc.poll() is None:
            self.proc.terminate()
        self.proc = None

    def set(self, voices):
        key = tuple((c, round(f), v) for c, f, v in voices)
        if key == self.key and (self.win or not key or (self.proc and self.proc.poll() is None)):
            return
        self.stop()
        self.key = key
        if not key or not self.available:
            return
        path = self.dir / ("brico68k_ssg_" + "_".join(f"{c}{f}v{v}" for c, f, v in key) + ".wav")
        try:
            if not path.is_file():
                path.write_bytes(ssg_wav(voices, seconds=1.0 if self.win else 20.0))
            if self.win:
                w = self.win
                w.PlaySound(str(path), w.SND_FILENAME | w.SND_ASYNC | w.SND_LOOP | w.SND_NODEFAULT)
            else:
                self.proc = subprocess.Popen([self.player, str(path)], stdout=subprocess.DEVNULL,
                                             stderr=subprocess.DEVNULL)
        except (OSError, RuntimeError):
            self.available = False


def core_label():
    try:
        p = core_path()
    except RuntimeError as e:
        return str(e)
    return f"C ({p.name})" if p else "Python"


# MAME snk/neogeo_v.cpp create_rgb_lookups: 3900/2200/1000/470/220 ohm, dark = 8.2k pull-down
_G = [1 / 3900, 1 / 2200, 1 / 1000, 1 / 470, 1 / 220]
_SUM = sum(_G)
_LEVELS = [[round(255 * sum(g for i, g in enumerate(_G) if v >> i & 1) / (_SUM + (1 / 8200 if dark else 0)))
            for v in range(32)] for dark in (0, 1)]


def neo_rgb3(c):
    """Neo Geo colour word -> (r, g, b), 0-255 (MAME DAC model)."""
    d = c >> 15
    r = ((c >> 14) & 1) | ((c >> 7) & 0x1E)
    g = ((c >> 13) & 1) | ((c >> 3) & 0x1E)
    b = ((c >> 12) & 1) | ((c << 1) & 0x1E)
    L = _LEVELS[d]
    return L[r], L[g], L[b]


def neo_rgb(c):
    """Neo Geo colour word -> '#rrggbb' (MAME DAC model)."""
    return "#%02x%02x%02x" % neo_rgb3(c)


# ---------------------------------------------------------------------------
# Start-up check
# ---------------------------------------------------------------------------
def check_rom(path):
    """Problems with a ROM file: [(what, detail)]."""
    if not path:
        return [("Brico68k ROM", "not selected")]
    p = Path(path)
    if not p.is_file():
        return [("Brico68k ROM file", str(p))]
    data = p.read_bytes()
    if len(data) > 0x20000:
        return [("ROM of 128 KB or less", f"{p.name} is {len(data)} bytes")]
    if len(data) < 0xA0 + 6 or data[0x80:0x88] != b"BricoNeo":
        return [("BricoNeo header (magic 'BricoNeo' at $80)", f"{p.name}: not a Brico68k ROM")]
    if struct.unpack_from(">H", data, 4)[0] != 0x00C0:
        return [("68000 byte order (reset vector $00C0xxxx)", f"{p.name}: byte-swapped dump?")]
    try:
        parse_extensions(data)
    except Exception as e:
        return [("readable extension table at $A0", f"{p.name}: {e}")]
    return []


def startup_check(rom_path):
    missing = []
    if sys.version_info < (3, 8):
        missing.append(("Python 3.8 or newer", sys.version.split()[0]))
    try:
        core_path()
    except Exception as e:
        missing.append(("emulator core", str(e)))
    missing += check_rom(rom_path)
    return missing


def default_rom():
    for c in ROM_CANDIDATES:
        if (TOOL_DIR / c).is_file():
            return str(TOOL_DIR / c)
    return ""


def load_config():
    try:
        return json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}


def save_config(cfg):
    try:
        WORK_DIR.mkdir(parents=True, exist_ok=True)
        CONFIG_PATH.write_text(json.dumps(cfg, indent=2), encoding="utf-8")
    except Exception:
        pass


HELP_BUILTIN = ("Built-in: Help (this list), Reset (console reset), Power (power cycle: clears RAM), Clear,\n"
                "Delay ms and ; comment (as on the BricoNeo console). Run script... plays a whole file.\n"
                "Simulated hardware faults: Faults tab (text mode: --fault, see --fault help).\n"
                "Parameters: decimal, $hex or 0xhex, as on Brico16Bits (e.g. Dump $100000 16).\n")


def help_text(host):
    lines = [f"{len(host.exts)} extensions in this ROM:"]
    for n, a, t, d in host.exts:
        lines.append(f"  {n:<13} [{TYPE_NAMES.get(t, t)}] {d}")
    return "\n".join(lines) + "\n" + HELP_BUILTIN


# ---------------------------------------------------------------------------
# Text mode
# ---------------------------------------------------------------------------
def parse_script(text):
    """BricoNeo console script -> steps: ('cmd', line) / ('wait', seconds) / ('note', comment).
    Same conventions as the Brico16Bits console: ';' starts a comment, 'Delay ms' waits."""
    steps = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        if line.startswith(";"):
            steps.append(("note", line[1:].strip()))
        elif line.split()[0].lower() == "delay":
            parts = line.split()
            ms = parse_uint(parts[1]) if len(parts) > 1 else 0
            steps.append(("wait", ms / 1000.0))
        else:
            steps.append(("cmd", line))
    return steps


# ---------------------------------------------------------------------------
# The tests the window knows. A NEW EXTENSION NEEDS NO ENTRY: the list comes from the ROM's extension
# table; an unknown one goes to "Other", Run all runs it once and its last "=> ..." line is the verdict.
# Add an entry only to change that: category, wait after it, a LOOK / varies note...
# ---------------------------------------------------------------------------
def _t(cat, look=None, varies=None, verdict_only=None, wait=0.0, twice=0.0, resets=False, last=False):
    """cat: group in the window ("Tools": not run by Run all, needs parameters); look: what to look at or
    listen to (no automatic verdict); varies / verdict_only: real console log comparison notes; wait: s
    to let it run after its EOT; twice: run it again after that many s (TestWatchdog); resets: it resets
    the console on purpose (needs the watchdog); last: Run all runs it last (its screen stays)."""
    return dict(cat=cat, look=look, varies=varies, verdict_only=verdict_only, wait=wait, twice=twice,
                resets=resets, last=last)


TESTS = {
    "TestChip": _t("Overview"),
    "TestBus": _t("Overview"),
    "TestWRAM": _t("Memory"),
    "TestBRAM": _t("Memory"),
    "TestPRAM": _t("Memory"),
    "TestDecode": _t("Memory"),
    "TestVRAM": _t("Video"),
    "TestLSPC": _t("Video"),
    "TestTiming": _t("Video", verdict_only="the measured cycle counts can differ slightly on a real board"),
    "TestGfx": _t("Video", look="Look at the screen: labels, fix tiles, flips, 8 x 4 tiles, H and V shrink (drawn "
                                "from VRAM; V shrink approximated, no L0 ROM). No tiles without a game or the test "
                                "cartridge."),
    "TestDAC": _t("Video", last=True,
                  look="Look at the screen: 16 bands, one colour bit each (a black band = dead bit)."),
    "TestZ80": _t("Sound"),
    "TestAudio": _t("Sound", wait=4.0),                            # the 68000 beeps for ~3.5 s
    "TestFM": _t("Sound", wait=1.0,                            # the jingle lasts ~0.6 s
                     look="Listen: the built-in test M1 plays a short jingle on the YM2610 SSG (C E G C); a real "
                          "cartridge M1 plays its own eyecatcher music, which is not emulated (FM / ADPCM)."),
    "TestSsg": _t("Sound", wait=0.5,                            # the chime lasts ~0.15 s
                  look="Listen: the built-in test M1 plays a two-note chime on the YM2610 SSG; a real M1 plays "
                       "its own coin chime (SSG, noise and timer A: only the SSG tones are emulated)."),
    "TestInp": _t("Inputs and system", varies="depends on the controllers, switches and memory card plugged in"),
    "TestStatusA": _t("Inputs and system", varies="depends on coins, service button and memory card"),
    "TestSystype": _t("Inputs and system", varies="depends on the board and its jumpers"),
    "TestVectors": _t("Inputs and system"),
    "TestWatchdog": _t("Inputs and system", twice=2.0, resets=True),
    "CartTest": _t("Cartridge", varies="depends on the cartridge: insert the same game set in the emulator "
                                       "(Cartridge tab) to compare"),
    "CartDiag": _t("Cartridge"),
    **{n: _t("Tools") for n in ("Version", "Echo", "Read", "Write", "WriteB", "Dump", "Color")},
}
CATEGORIES = []                       # [(group, [names])] in TESTS order, "Tools" last
for _n, _s in TESTS.items():
    if not CATEGORIES or CATEGORIES[-1][0] != _s["cat"]:
        CATEGORIES.append((_s["cat"], []))
    CATEGORIES[-1][1].append(_n)
TOOLS = {n for n, s in TESTS.items() if s["cat"] == "Tools"}
LOOK = {n: s["look"] for n, s in TESTS.items() if s["look"]}
VARIES = {n: s["varies"] for n, s in TESTS.items() if s["varies"]}
VERDICT_ONLY = {n: s["verdict_only"] for n, s in TESTS.items() if s["verdict_only"]}


# ---------------------------------------------------------------------------
# Real console log vs emulator
# ---------------------------------------------------------------------------


def _norm(text):
    return [l.rstrip() for l in (text or "").splitlines() if l.strip()]


def replay_log(core, rom, entries):
    """Runs the commands of a real log, in order, on a powered-on core.
    Returns the emulator output for each entry (None: comment, Delay or console built-in)."""
    return [exp for _, exp in replay_iter(core, rom, entries)]


def replay_iter(core, rom, entries):
    host = Host(core, rom)
    for e in entries:
        out = []
        words = e["line"].split()
        w = words[0].lower() if words else ""
        if e["name"] == ";" or not words:
            out.append(None)
        elif w == "delay":
            ms = parse_uint(words[1]) if len(words) > 1 else 0
            for _ in range(round(ms * 60 / 1000)):
                core.lib.neo_run_frame()
            out.append(None)
        elif w == "reset":                             # Brico16Bits Reset: the watchdog resets the console
            core.lib.neo_reset()
            for _ in range(60):
                core.lib.neo_run_frame()
            out.append(None)
        elif w[:1] in "*@" or host.find(w) is None:    # loop / binary modes and other built-ins
            out.append(None)
        else:
            out.append(host.run_blocking(e["line"])[1])
        yield e, out[0]


def compare_rows(entries, expected):
    rows = []
    for e, exp in zip(entries, expected):
        if exp is None:
            continue
        name, real = e["name"], e["output"]
        rs, rv = classify(name, "timeout" if "[Timeout]" in real else "eot", real)
        es, _ = classify(name, "timeout" if "[Timeout]" in exp else "eot", exp)
        if _norm(real) == _norm(exp):
            match = "same"
        elif name in VARIES:
            match = "varies"
        elif name in VERDICT_ONLY and rs == es:
            match = "same verdict"
        else:
            match = "DIFFERENT"
        rows.append({"line": e["line"], "name": name, "real": real, "expected": exp, "real_status": rs,
                     "real_verdict": rv, "exp_status": es, "match": match,
                     "note": VARIES.get(name) or VERDICT_ONLY.get(name, "")})
    return rows


def compare_diff(row):
    import difflib
    d = difflib.unified_diff(_norm(row["expected"]), _norm(row["real"]), "expected (emulator)", "real console",
                             lineterm="", n=1)
    return "\n".join(list(d)[2:])


def compare_summary(rows):
    n = {k: sum(1 for r in rows if r["match"] == k) for k in ("same", "same verdict", "varies", "DIFFERENT")}
    fails = sum(1 for r in rows if r["real_status"] == "FAIL")
    return (f"{len(rows)} commands compared: {n['same']} same, {n['same verdict']} same verdict, "
            f"{n['varies']} vary with the hardware plugged in, {n['DIFFERENT']} different; "
            f"{fails} FAIL on the real console")


def compare_report(rows, log_name, setup):
    out = [f"Real console log: {log_name}", f"Emulator: {setup}", ""]
    out.append(f"  {'Command':<26}{'Real':<9}{'Emulator':<10}Match")
    for r in rows:
        out.append(f"  {r['line'][:25]:<26}{STATUS_STYLE[r['real_status']][0]:<9}"
                   f"{STATUS_STYLE[r['exp_status']][0]:<10}{r['match']}")
    out += ["", compare_summary(rows)]
    for r in rows:
        if r["match"] in ("DIFFERENT", "varies", "same verdict"):
            out += ["", f"=== {r['line']} ({r['match']}{': ' + r['note'] if r['note'] else ''})", compare_diff(r)]
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------------------
# Fault dictionary: which modelled fault explains a real console log
# ---------------------------------------------------------------------------
def all_single_faults():
    """Every single fault the core models: data bits and address lines stuck at 0/1, WRAM chip dead."""
    out = []
    for region in FAULT_REGIONS.values():
        if region == 6:                      # cartridge slot: needs a cartridge, not in console logs yet
            continue
        out += [(region, 0, bit, v) for bit in range(DATA_BITS[region] + 1) for v in (0, 1)]
        if region in ADDR_RANGE:
            lo, hi = ADDR_RANGE[region]
            out += [(region, 1, bit, v) for bit in range(lo, hi + 1) for v in (0, 1)]
    out += [(0, 2, 0, 0), (0, 2, 0, 1)]
    # address decoding (TestDecode): a mirror line the decoder does not ignore, then WRAM writes into the palette
    out += [(r, 4, bit, v) for r, (lo, hi) in SEL_RANGE.items() for bit in range(lo, hi + 1) for v in (0, 1)]
    return out + [(0, 5, 0, 1)]


_DX = {}


def _dx_init(rom, raw, z80, wd, limit=None):
    if "core" not in _DX:
        _DX["core"] = Core(core_path())
    _DX.update(rom=rom, z80=z80, wd=wd, limit=limit,
               entries=parse_console_log(raw, [n for n, *_ in parse_extensions(rom)]))


def _dx_score(fault, limit=None):
    """(fault, commands compared, commands still different) for one candidate (None = healthy).
    Stops early (None as the list) once more than `limit` commands differ: worse than no fault at all."""
    core, rom = _DX["core"], _DX["rom"]
    limit = _DX.get("limit") if limit is None else limit
    core.load(rom); core.power_on(); core.lib.neo_set_options(_DX["z80"], _DX["wd"])
    apply_faults(core, [fault] if fault else [])
    for _ in range(60):
        core.lib.neo_run_frame()
    n, diff = 0, []
    for e, exp in replay_iter(core, rom, _DX["entries"]):
        if exp is None:
            continue
        n += 1
        if compare_rows([e], [exp])[0]["match"] == "DIFFERENT":
            diff.append(e["line"])
            if limit is not None and len(diff) > limit:
                return fault, None, None
    return fault, n, diff


def diagnose(rom, raw, z80=None, wd=1, progress=None):
    """Replays the log under every single modelled fault and ranks them by commands left unexplained.
    z80=None tries both Z80 settings on a healthy console and keeps the closer one."""
    if z80 is None:
        scores = {}
        for mode in (1, 0):
            _dx_init(rom, raw, mode, wd)
            scores[mode] = len(_dx_score(None, limit=None)[2])
        z80 = 1 if scores[1] <= scores[0] else 0
    _dx_init(rom, raw, z80, wd)
    base = _dx_score(None)
    limit = len(base[2])
    faults = all_single_faults()
    results = []
    workers = max(1, min(8, (os.cpu_count() or 2) - 1))
    try:
        from concurrent.futures import ProcessPoolExecutor
        with ProcessPoolExecutor(max_workers=workers, initializer=_dx_init, initargs=(rom, raw, z80, wd, limit)) as ex:
            for i, r in enumerate(ex.map(_dx_score, faults, chunksize=4)):
                results.append(r)
                if progress:
                    progress(i + 1, len(faults))
    except Exception:                                   # no multiprocessing here: one process does it all
        results = []
        _DX["limit"] = limit
        for i, f in enumerate(faults):
            results.append(_dx_score(f))
            if progress:
                progress(i + 1, len(faults))
    results = sorted((r for r in results if r[2] is not None), key=lambda r: (len(r[2]), r[0]))
    return {"z80": z80, "watchdog": wd, "tried": len(faults), "compared": base[1], "healthy_diff": base[2],
            "candidates": [{"fault": describe_fault(f), "spec": fault_spec(f), "explained": n - len(d),
                            "total": n, "still_different": d} for f, n, d in results]}


def diagnose_report(d, log_name, top=8):
    out = [f"Diagnosis of {log_name}: {d['tried']} single faults tried "
           f"(Z80 {'test M1' if d['z80'] else 'no program'}, watchdog {'on' if d['watchdog'] else 'off'})."]
    n = d["compared"]
    if not d["healthy_diff"]:
        out.append(f"The log matches a healthy console ({n}/{n} commands): nothing to explain.")
        return "\n".join(out) + "\n"
    out.append(f"Healthy console: {n - len(d['healthy_diff'])}/{n} commands match; different: "
               + ", ".join(d["healthy_diff"]))
    better = [c for c in d["candidates"] if len(c["still_different"]) < len(d["healthy_diff"])]
    exact = [c for c in better if not c["still_different"]]
    best = exact + [c for c in better if c["still_different"]][:3] if exact else better[:top]
    if not best:
        out.append("No single modelled fault explains the log better than a healthy console.")
    else:
        out.append("Best candidates (equal scores = the log cannot tell them apart):")
        for i, c in enumerate(best, 1):
            rest = "explains every command" if not c["still_different"] else \
                "still different: " + ", ".join(c["still_different"])
            out.append(f"  {i}. {c['fault']}  [{c['spec']}]  {c['explained']}/{c['total']}, {rest}")
        if exact and all(c["spec"].startswith("bios:") for c in exact):
            out.append("The console never answers: a BIOS socket address line (68000 -> BricoNeo) is suspect, "
                       "and the log cannot say which one. Look at the screen after power-on: with A15 or A16 stuck at 0 "
                       "the firmware shows 16 bands, A1 at the top (red = stuck at 0); with a line stuck at 1, or "
                       "A1-A14: no boot, reseat the BricoNeo, then BricoNeo Trace and a continuity meter.")
    out.append("Limits: one stuck-at fault at a time, in the modelled chips only (WRAM, palette RAM, VRAM, "
               "line counter, BIOS socket address lines). Intermittent faults, shorts between lines, timing "
               "faults and other chips are not in the dictionary.")
    return "\n".join(out) + "\n"


def main_cli(argv):
    import argparse
    ap = argparse.ArgumentParser(description=APP_NAME)
    ap.add_argument("--rom", default=None)
    ap.add_argument("--run", nargs="*", default=None, help="commands to run, e.g. \"TestWRAM\" \"Echo 1234\"")
    ap.add_argument("--script", metavar="FILE", help="run a BricoNeo console script (';' comments, 'Delay ms')")
    ap.add_argument("--test", nargs="*", metavar="COMMAND",
                    help="test extensions: verdict + Brico16Bits rule check of each one (default: all, as Run all; "
                         "else command lines, e.g. TestWRAM \"MyTest 3\"); exit code 1 on a FAIL. Python core")
    ap.add_argument("--compare", metavar="LOG",
                    help="compare a session log of the real BricoNeo console with the emulator")
    ap.add_argument("--diagnose", metavar="LOG",
                    help="find which modelled fault explains a real console log (fault dictionary)")
    ap.add_argument("--json", action="store_true", help="--compare / --diagnose: machine-readable output")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--z80", choices=["testm1", "none"], default=None,
                    help="testm1 (default): Z80 runs the built-in test M1; none: Z80 without program "
                         "(--diagnose picks the closer one when not given)")
    ap.add_argument("--no-watchdog", action="store_true",
                    help="no watchdog, like MAME's aes driver (real AES and MVS boards have one, in NEO-B1)")
    ap.add_argument("--watchdog", action="store_true", help=argparse.SUPPRESS)   # default since 1.7, kept for old scripts
    ap.add_argument("--fault", action="append", default=[], metavar="SPEC",
                    help="simulated hardware fault, repeatable, e.g. wram:data:5:1 (see --fault help)")
    ap.add_argument("--cart", default="none", metavar="CART",
                    help="cartridge: none (default), test (built-in test cartridge), diag (diagnostic PROG "
                         "board) or a game ROM set (folder or MAME .zip)")
    ap.add_argument("--cart-list", metavar="XML", help="official MAME list (hash/neogeo.xml): identifies the "
                    "ROM set by CRC32, loads it with the list's layout and checks every chip")
    ap.add_argument("--png", metavar="FILE", help="after --run / --script: save the screen (backdrop, fix layer "
                    "and sprites drawn from VRAM, x2) as a PNG")
    ap.add_argument("rom_pos", nargs="?")
    a = ap.parse_args(argv)
    if "help" in [f.lower() for f in a.fault]:
        print(FAULT_HELP)
        return 0
    try:
        faults = [parse_fault(f) for f in a.fault]
    except ValueError as e:
        print(f"ERROR: {e}")
        return 2
    rom_path = a.rom or a.rom_pos or default_rom()
    missing = startup_check(rom_path)
    for w, d in missing:
        print(f"MISSING: {w} -> {d}")
    if a.check:
        print("OK: nothing missing" if not missing else f"{len(missing)} missing item(s)")
        return 1 if missing else 0
    if missing:
        return 1
    rom = Path(rom_path).read_bytes()
    if a.diagnose:
        try:
            raw = Path(a.diagnose).read_bytes()
        except OSError as e:
            print(f"ERROR: cannot read the log: {e}")
            return 2
        if not parse_console_log(raw, [n for n, *_ in parse_extensions(rom)]):
            print("ERROR: no BricoNeo command found in this log ('> Command' lines)")
            return 2
        core_path()                                   # a bad BRICO68K_CORE fails here, not in the workers

        def prog(i, n):
            if i % 16 == 0 or i == n:
                print(f"PROGRESS {i} {n}", file=sys.stderr, flush=True)
        d = diagnose(rom, raw, None if a.z80 is None else (1 if a.z80 == "testm1" else 0),
                     0 if a.no_watchdog else 1, prog)
        print(json.dumps(d) if a.json else diagnose_report(d, Path(a.diagnose).name), end="\n" if a.json else "")
        return 0
    try:
        cart = make_cart(a.cart) if a.cart in ("none", "test", "diag") else load_cartridge(a.cart, a.cart_list)
    except (OSError, ValueError) as e:
        print(f"ERROR: cartridge: {e}")
        return 2
    core = Core(None if a.test is not None else core_path())     # the rule check needs the Python core
    core.load(rom)
    core.load_cart(cart)
    if cart.kind != "none":
        print("CART: " + cart.report().replace("\n", "\nCART: "))
    core.power_on()
    core.lib.neo_set_options(0 if a.z80 == "none" else 1, 0 if a.no_watchdog else 1)
    apply_faults(core, faults)
    for f in faults:
        print(f"FAULT: {describe_fault(f)}")
    for _ in range(60):
        core.lib.neo_run_frame()
    host = Host(core, rom)
    if a.test is not None:
        return test_cli(host, a.test, not a.no_watchdog, a.json)
    if a.compare:
        try:
            raw = Path(a.compare).read_bytes()
        except OSError as e:
            print(f"ERROR: cannot read the log: {e}")
            return 2
        entries = parse_console_log(raw, [n for n, *_ in host.exts])
        if not entries:
            print("ERROR: no BricoNeo command found in this log ('> Command' lines)")
            return 2
        rows = compare_rows(entries, replay_log(core, rom, entries))
        setup = (f"Z80 {'no program' if a.z80 == 'none' else 'test M1'}, watchdog "
                 f"{'off' if a.no_watchdog else 'on'}, " + (", ".join(describe_fault(f) for f in faults) or "no fault"))
        if a.json:
            print(json.dumps({"setup": setup, "summary": compare_summary(rows),
                              "rows": [dict(r, diff=compare_diff(r)) for r in rows]}))
        else:
            print(compare_report(rows, Path(a.compare).name, setup), end="")
        return 0
    if a.script:
        try:
            steps = parse_script(Path(a.script).read_text(encoding="utf-8", errors="replace"))
        except OSError as e:
            print(f"ERROR: cannot read the script: {e}")
            return 2
    else:
        steps = [("cmd", line) for line in (a.run or ["Help"])]
    for kind, arg in steps:
        if kind == "note":
            print(f"; {arg}")
            continue
        if kind == "wait":
            print(f"> Delay {arg * 1000:.0f}")
            for _ in range(round(arg * 60)):
                core.lib.neo_run_frame()
            continue
        print(f"> {arg}")
        if arg.strip().lower() == "help":
            print(help_text(host), end="")
            continue
        st, text, secs = host.run_blocking(arg)
        print(text, end="")
        print(f"[{st}, {secs * 1000:.0f} ms emulated]")
    if a.png:
        for _ in range(4):                            # a few frames: the backdrop lines of the last command
            core.lib.neo_run_frame()
        cache = {}
        try:
            write_png(a.png, [[cache.get(c) or cache.setdefault(c, neo_rgb3(c)) for c in row]
                              for row in core.screen()], 2)
        except OSError as e:
            print(f"ERROR: cannot write the picture: {e}")
            return 2
        print(f"SCREEN: {a.png}" + ("" if cart.tiles else " (no tiles: backdrop only)"))
    return 0


# ---------------------------------------------------------------------------
# Diagnostic catalogue: how the tests are grouped, run and judged
# ---------------------------------------------------------------------------
CHK_PROGRESS, CHK_PROG_MAGIC = 0x10FFF0, 0x10FFF2   # TestChip progress word and its magic ($C4EC)
LAMP_OFF = ("#e6e9ed", "#59636e")     # status bar pill when off: background, text
STATUS_STYLE = {   # status -> (label, foreground, background)
    "PASS": ("PASS", "#1a7f37", "#dafbe1"), "FAIL": ("FAIL", "#cf222e", "#ffebe9"),
    "WARN": ("CHECK", "#9a6700", "#fff8c5"), "NA": ("N/A", "#59636e", "#eef1f4"),
    "INFO": ("INFO", "#0969da", "#ddf4ff"), "LOOK": ("LOOK", "#8250df", "#fbefff"),
    "RUN": ("RUNNING", "#0969da", "#ddf4ff"), "ARMED": ("ARMED", "#9a6700", "#fff8c5"),
    "": ("", "#59636e", "#ffffff"),
}


def classify(name, status, text):
    """(status, one-line verdict) from a test output, as a technician would read it."""
    if status == "timeout":
        return "FAIL", "Timeout: no end-of-transmission within 3 s (the 68000 is stuck or busy)."
    if status == "error":
        return "FAIL", text.strip().splitlines()[0] if text.strip() else "Error"
    lines = [l.strip() for l in text.splitlines()]
    verdicts = [l for l in lines if l.startswith("=>")]
    errors = [l for l in lines if l.startswith("ERROR")]
    exc = [l for l in lines if "EXCEPTION" in l.upper() and "***" in l]
    if exc:
        return "FAIL", (exc[-1].strip("* ") + ". Most extensions use WRAM for the stack: "
                        "if TestWRAM fails, fix that first.")
    if errors:
        return "FAIL", errors[-1]
    if name == "TestWatchdog" and any("ARMED" in l for l in lines):
        return "ARMED", "Armed: the watchdog is being starved; run TestWatchdog again to read the result."
    if verdicts:
        v = verdicts[-1]
        s = v.lower()
        if "n/a" in s:
            return "NA", v
        if "inconclusive" in s or "check" in s or "cannot run" in s:
            return "WARN", v
        if "success" in s:
            return "PASS", v
        if "fail" in s or "error" in s:
            return "FAIL", v
        return "INFO", v
    if name == "TestAudio" and "ACK $01 received" in text:
        return "PASS", "Z80 ACK received."
    if name in LOOK:
        return "LOOK", LOOK[name]
    if name in TOOLS:
        return "INFO", "Done."
    return "INFO", "Report only, no automatic verdict: read the output."


def run_all_plan(names, watchdog):
    """Steps for Run all: ('cmd', line) / ('wait', seconds) / ('skip', name, status, why)."""
    plan, lasts = [], []
    order = [n for n in TESTS if n not in TOOLS]
    order += [n for n in names if n not in order and n not in TOOLS]      # extensions not in TESTS
    for n in order:
        if n not in names:
            continue
        s = TESTS.get(n) or _t("Other")
        if s["last"]:
            lasts.append(("cmd", n))
        elif s["resets"] and not watchdog:
            plan.append(("skip", n, "NA", "Watchdog switched off in Settings (as in MAME's aes driver): "
                                          "enable it in Settings to run this test."))
        else:
            plan.append(("cmd", n))
            if s["wait"]:
                plan.append(("wait", s["wait"]))
            if s["twice"]:
                plan += [("wait", s["twice"]), ("cmd", n)]
    return plan + lasts


def test_plan(host, lines, watchdog):
    """--test steps: ('cmd', line, resets) / ('wait', s) / ('skip', name, status, why)."""
    if not lines:
        plan = run_all_plan([n for n, *_ in host.exts], watchdog)
    else:
        plan = []
        for line in lines:
            s = TESTS.get(line.split()[0]) or _t("Other")
            plan.append(("cmd", line))
            if s["wait"]:
                plan.append(("wait", s["wait"]))
            if s["twice"]:
                plan += [("wait", s["twice"]), ("cmd", line)]
    return [(st[0], st[1], (TESTS.get(st[1].split()[0]) or _t("Other"))["resets"]) if st[0] == "cmd" else st
            for st in plan]


def test_cli(host, lines, watchdog, as_json=False):
    """--test: each command with its verdict (as Run all) and the Brico16Bits rule check (emu_host.ExtCheck)."""
    lib = host.core.lib
    rows = []
    plan = test_plan(host, lines, watchdog)
    for i, step in enumerate(plan):
        if as_json:
            print(f"PROGRESS {i} {len(plan)}", file=sys.stderr, flush=True)
        if step[0] == "wait":
            for _ in range(round(step[1] * 60)):
                lib.neo_run_frame()
            continue
        if step[0] == "skip":
            rows.append(dict(line=step[1], status=step[2], verdict=step[3], ms=0, rules=[], output=""))
        else:
            line, resets = step[1], step[2]
            name = line.split()[0]
            st, text, secs, rules = check_command(host, line, resets)
            status, verdict = classify(host.find(name)[0] if host.find(name) else name, st, text)
            if any(lv == "FAIL" for lv, _ in rules):
                status = "FAIL"
            elif rules and status in ("PASS", "INFO", "LOOK"):
                status = "WARN"
            rows.append(dict(line=line, status=status, verdict=verdict, ms=round(secs * 1000), output=text,
                             rules=[dict(level=lv, text=t) for lv, t in rules]))
        r = rows[-1]
        if not as_json:
            print(f"{STATUS_STYLE[r['status']][0]:7s} {r['line']:22s} {r['ms']:6d} ms  {r['verdict']}", flush=True)
            for f in r["rules"]:
                print(f"{'':8s}rule {f['level']}: {f['text']}")
    counts = {}
    for r in rows:
        counts[r["status"]] = counts.get(r["status"], 0) + 1
    summary = ", ".join(f"{n} {STATUS_STYLE[k][0].lower()}" for k, n in counts.items())
    if as_json:
        print(json.dumps({"summary": counts, "rows": rows}))
    else:
        print(f"--- {len(rows)} run(s): {summary}. Rules: Brico16Bits protocol as modelled from its source "
              "(output with IRQs masked from ROM code, P1-P3 read first, one EOT under 3 s, < 2047 words, "
              "watchdog, polling after the EOT, loop-mode repeat); checked in emulation only.")
    return 1 if counts.get("FAIL") else 0


# ---------------------------------------------------------------------------
# Window
# ---------------------------------------------------------------------------
def main_gui(rom_arg=None):
    import tkinter as tk
    from tkinter import filedialog, ttk

    cfg = load_config()
    root = tk.Tk()
    root.title(f"{APP_NAME} {APP_VERSION}")
    root.minsize(1000, 660)
    geo = cfg.get("geometry") or "1280x820"
    mg = re.match(r"(\d+)x(\d+)([+-]-?\d+)?([+-]-?\d+)?$", geo)
    if mg:
        w, h = min(int(mg.group(1)), root.winfo_screenwidth()), min(int(mg.group(2)), root.winfo_screenheight())
        geo = f"{max(w, 1000)}x{max(h, 660)}"
        if mg.group(3) and mg.group(4):
            x, y = int(mg.group(3).replace("+", "")), int(mg.group(4).replace("+", ""))
            if 0 <= x < root.winfo_screenwidth() - 100 and 0 <= y < root.winfo_screenheight() - 100:
                geo += f"+{x}+{y}"
    root.geometry(geo if mg else "1280x820")

    # --- theme (light) -----------------------------------------------------------
    C = dict(bg="#f3f5f7", panel="#ffffff", field="#ffffff", border="#d0d7de", text="#1f2328",
             muted="#59636e", accent="#0969da", ok="#1a7f37", warn="#9a6700", err="#cf222e",
             btn="#eef1f4", btn_hover="#e1e6eb", head="#f6f8fa")
    ui = "Segoe UI" if IS_WIN else "DejaVu Sans"
    F = (ui, 10); FB = (ui, 10, "bold"); FS = (ui, 9); FT = (ui, 15, "bold"); FV = (ui, 13, "bold")
    mono = ("Consolas", 10) if IS_WIN else ("DejaVu Sans Mono", 10)
    root.configure(bg=C["bg"])
    sty = ttk.Style(root)
    sty.theme_use("clam")
    sty.configure(".", background=C["bg"], foreground=C["text"], fieldbackground=C["field"],
                  bordercolor=C["border"], lightcolor=C["border"], darkcolor=C["border"], font=F)
    for name, bg in (("TFrame", C["bg"]), ("Card.TFrame", C["panel"]), ("Head.TFrame", C["panel"])):
        sty.configure(name, background=bg)
    sty.configure("Card.TFrame", borderwidth=1, relief="solid")
    sty.configure("TLabel", background=C["bg"], foreground=C["text"])
    for name, fg, font in (("Card.TLabel", C["text"], F), ("CardMuted.TLabel", C["muted"], FS),
                           ("CardBold.TLabel", C["text"], FB), ("Title.TLabel", C["text"], FT),
                           ("HeadMuted.TLabel", C["muted"], F)):
        sty.configure(name, background=C["panel"], foreground=fg, font=font)
    sty.configure("TButton", background=C["btn"], foreground=C["text"], padding=(10, 4), relief="flat")
    sty.map("TButton", background=[("disabled", C["btn"]), ("active", C["btn_hover"])],
            foreground=[("disabled", "#8c959f")])
    sty.configure("Accent.TButton", background=C["accent"], foreground="#ffffff")
    sty.map("Accent.TButton", background=[("disabled", C["btn"]), ("active", "#0550ae")],
            foreground=[("disabled", "#8c959f")])
    sty.configure("TCheckbutton", background=C["panel"]); sty.map("TCheckbutton", background=[("active", C["panel"])])
    sty.configure("TRadiobutton", background=C["panel"]); sty.map("TRadiobutton", background=[("active", C["panel"])])
    sty.configure("TCombobox", fieldbackground=C["field"], background=C["btn"], arrowcolor=C["text"])
    sty.map("TCombobox", fieldbackground=[("readonly", C["field"])])
    sty.configure("Treeview", background=C["panel"], fieldbackground=C["panel"], foreground=C["text"],
                  rowheight=24, borderwidth=0, font=F)
    sty.map("Treeview", background=[("selected", "#ddf4ff")], foreground=[("selected", C["text"])])
    sty.configure("Treeview.Heading", background=C["head"], foreground=C["muted"], relief="flat", font=FS)
    sty.configure("TNotebook", background=C["bg"], borderwidth=0, tabmargins=(0, 0, 0, 0))
    sty.configure("TNotebook.Tab", background=C["btn"], foreground=C["muted"], padding=(16, 6), font=F)
    sty.map("TNotebook.Tab", background=[("selected", C["panel"])], foreground=[("selected", C["text"])])
    sty.configure("Busy.Horizontal.TProgressbar", troughcolor=C["head"], background=C["accent"])

    st = {"core": None, "host": None, "rom": None, "running": False, "t_last": 0.0, "fps_t": time.time(),
          "fps_n": 0, "fps": 0.0, "history": list(cfg.get("history", []))[-50:], "hist_i": 0,
          "busy_t0": None, "busy_name": "", "busy_line": "", "screens": [], "colours": [None] * 224,
          "results": {}, "plan": [], "plan_total": 0, "wait_until": None, "faults": [], "log": [],
          "cart": None}
    st["hist_i"] = len(st["history"])
    for spec in cfg.get("faults", []):
        try:
            st["faults"].append(parse_fault(spec))
        except ValueError:
            pass

    # --- header ----------------------------------------------------------------------
    head = ttk.Frame(root, style="Head.TFrame", padding=(16, 10)); head.pack(fill="x")
    b_pause = ttk.Button(head, text="Pause", width=6, command=lambda: toggle_pause()); b_pause.pack(side="right")
    b_reset = ttk.Button(head, text="Reset", width=6, command=lambda: do_reset()); b_reset.pack(side="right", padx=6)
    b_power = ttk.Button(head, text="Power on", width=9, style="Accent.TButton", command=lambda: power_on())
    b_power.pack(side="right")
    ttk.Label(head, text=APP_NAME, style="Title.TLabel").pack(side="left")
    ttk.Label(head, text=f" {APP_VERSION}", style="HeadMuted.TLabel").pack(side="left", pady=(5, 0))
    rom_chip = ttk.Frame(head, style="Head.TFrame"); rom_chip.pack(side="left", padx=(20, 0))
    rom_name = tk.StringVar(); rom_info = tk.StringVar()
    b_open = ttk.Button(rom_chip, text="Change ROM...", command=lambda: pick_rom()); b_open.pack(side="right")
    ttk.Label(rom_chip, textvariable=rom_name, style="CardBold.TLabel").pack(side="left")
    ttk.Label(rom_chip, textvariable=rom_info, style="HeadMuted.TLabel").pack(side="left", padx=(8, 8))
    tk.Frame(root, height=1, bg=C["border"]).pack(fill="x")

    missing_var = tk.StringVar()
    missing_box = tk.Label(root, textvariable=missing_var, justify="left", anchor="w", bg="#ffebe9", fg="#82071e",
                           padx=16, pady=8, font=F)

    # --- status bar --------------------------------------------------------------------
    sbar = tk.Frame(root, bg=C["panel"], highlightthickness=1, highlightbackground=C["border"])
    sbar.pack(fill="x", side="bottom")
    lamps = {}
    for key, label in (("cpu", "68000 off"), ("host", "Host"), ("z80", "Z80"), ("sound", "Silent"), ("cart", "No cartridge"), ("fault", "No fault")):
        # a pill: solid colour + white text when on, pale grey when off (a coloured dot alone was too small)
        f = tk.Frame(sbar, bg=LAMP_OFF[0], padx=8, pady=2); f.pack(side="left", padx=(8, 0), pady=5)
        d = tk.Label(f, text="○", fg=LAMP_OFF[1], bg=LAMP_OFF[0], font=(F[0], F[1] + 3)); d.pack(side="left")
        t = tk.Label(f, text=label, fg=LAMP_OFF[1], bg=LAMP_OFF[0], font=(FS[0], FS[1], "bold")); t.pack(side="left", padx=(4, 0))
        lamps[key] = (d, t, f)
    status = tk.StringVar()
    tk.Label(sbar, textvariable=status, fg=C["muted"], bg=C["panel"], font=FS).pack(side="right", padx=12)
    busy_var = tk.StringVar()
    busy_bar = ttk.Progressbar(sbar, style="Busy.Horizontal.TProgressbar", length=120, maximum=3.0)
    busy_bar.pack(side="right", padx=(0, 6))
    tk.Label(sbar, textvariable=busy_var, fg=C["accent"], bg=C["panel"], font=FS).pack(side="right", padx=6)

    # --- body: sidebar | notebook -----------------------------------------------------------
    body = ttk.Panedwindow(root, orient="horizontal"); body.pack(fill="both", expand=True, padx=12, pady=10)
    side = ttk.Frame(body, style="Card.TFrame", padding=10); body.add(side, weight=0)
